function cleanDropdownMasterData(appState = state) {
  const before = {
    services: [...(appState.services || [])],
    careOfList: [...(appState.careOfList || [])],
    staffMaster: [...(appState.staffMaster || [])],
    modeList: [...(appState.modeList || [])],
  };
  const usedServices = dedupeByNormalizedText((appState.files || []).map((file) => canonicalServiceType(file.serviceType)));
  const usedCareOf = dedupeByNormalizedText((appState.files || []).map((file) => file.careOf || "Direct"));
  appState.services = dedupeByNormalizedText([...defaultServices, ...usedServices]);
  appState.careOfList = usedCareOf.length ? usedCareOf : dedupeByNormalizedText(appState.careOfList || defaultCareOfList);
  appState.staffMaster = dedupeByNormalizedText([...(appState.staffMaster || []), ...defaultStaffMaster]);
  appState.modeList = dedupeByNormalizedText([...(appState.modeList || []), ...modes, ...(appState.files || []).map((file) => file.mode)]);
  if (JSON.stringify(before.services) !== JSON.stringify(appState.services) || JSON.stringify(before.careOfList) !== JSON.stringify(appState.careOfList)) {
    appState.auditLog = [
      ...(appState.auditLog || []),
      {
        id: crypto.randomUUID(),
        action: "Dropdown cleanup performed",
        details: {
          servicesBefore: before.services.length,
          servicesAfter: appState.services.length,
          careOfBefore: before.careOfList.length,
          careOfAfter: appState.careOfList.length,
          actionTaken: "Unused and duplicate Service Type/C/o dropdown entries removed from master lists only; file records preserved.",
        },
        user: appState.currentUser || "System",
        role: appState.currentRole || "",
        at: new Date().toISOString(),
      },
    ].slice(-1000);
  }
}

function saveState(options = {}) {
  if (!options.skipMerge) mergeLatestSharedStateBeforeSave();
  refreshFileStaffLinks();
  saveTabSession();
  try {
    if (isSupabaseMode()) {
      // The central API is authoritative. Avoid filling browser storage with the full database.
      localStorage.removeItem(STORAGE_KEY);
    } else {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(sharedStateForStorage(state)));
    }
    localStorage.setItem(SYNC_EVENT_KEY, String(Date.now()));
  } catch (error) {
    console.warn("Browser cache write skipped; the app will continue using central data.", error);
  }
  if (options.fullRemote && !options.skipRemote) saveStateToApi();
  if (syncChannel) syncChannel.postMessage({ type: "state-updated", at: Date.now() });
}

function saveViewState() {
  saveTabSession();
}

function apiToken() {
  return sessionStorage.getItem(API_TOKEN_KEY) || "";
}

function setApiToken(token) {
  if (token) sessionStorage.setItem(API_TOKEN_KEY, token);
  else sessionStorage.removeItem(API_TOKEN_KEY);
}

function setApiSession(session) {
  setApiToken(session?.access_token || "");
  if (session?.refresh_token) sessionStorage.setItem(API_REFRESH_TOKEN_KEY, session.refresh_token);
  else sessionStorage.removeItem(API_REFRESH_TOKEN_KEY);
}

function isSupabaseMode() {
  return sessionStorage.getItem(API_MODE_KEY) === "supabase" && Boolean(apiToken());
}

function allowLocalLoginFallback() {
  const host = location.hostname;
  return location.protocol === "file:" || host === "localhost" || host === "127.0.0.1";
}

async function apiJson(path, options = {}) {
  return backendApiJson(path, options);
}

function desktopNotificationsSupported() {
  return window.isSecureContext && "serviceWorker" in navigator && "PushManager" in window && "Notification" in window;
}

function urlBase64ToUint8Array(value = "") {
  const padding = "=".repeat((4 - (value.length % 4)) % 4);
  const base64 = (value + padding).replace(/-/g, "+").replace(/_/g, "/");
  return Uint8Array.from(atob(base64), (character) => character.charCodeAt(0));
}

async function registerDesktopNotificationWorker() {
  if (!desktopNotificationsSupported()) return null;
  if (!desktopServiceWorkerRegistration) {
    desktopServiceWorkerRegistration = await navigator.serviceWorker.register("/service-worker.js", { scope: "/" });
  }
  if (!desktopNotificationMessageBound) {
    navigator.serviceWorker.addEventListener("message", (event) => {
      if (event.data?.type === "OPEN_DESKTOP_NOTIFICATION") openDesktopNotificationTarget(event.data.notification || {});
      if (event.data?.type === "DESKTOP_PUSH_RECEIVED") refreshCentralState().catch(() => {});
    });
    desktopNotificationMessageBound = true;
  }
  return desktopServiceWorkerRegistration;
}

async function loadDesktopNotificationConfig(force = false) {
  if (!state.session?.loggedIn || !isSupabaseMode()) return null;
  if (force) desktopNotificationConfig = null;
  if (desktopNotificationConfigPromise) return desktopNotificationConfigPromise;
  desktopNotificationConfigPromise = (async () => {
    try {
      desktopNotificationConfig = await apiJson("/api/notifications/config");
      const registration = await registerDesktopNotificationWorker();
      const subscription = await registration?.pushManager?.getSubscription();
      currentDeviceSubscribed = Boolean(subscription);
      if (subscription && Notification.permission === "granted" && desktopNotificationConfig?.preferences?.desktop_enabled) {
        await apiJson("/api/notifications/subscribe", {
          method: "POST",
          body: JSON.stringify({ subscription: subscription.toJSON(), deviceLabel: desktopNotificationDeviceLabel() }),
        });
      }
    } catch (error) {
      console.warn("Desktop notification configuration unavailable", error);
      desktopNotificationConfig = { supported: false, error: error.message };
    } finally {
      desktopNotificationConfigPromise = null;
    }
    return desktopNotificationConfig;
  })();
  return desktopNotificationConfigPromise;
}

function desktopNotificationDeviceLabel() {
  let label = localStorage.getItem(DESKTOP_NOTIFICATION_DEVICE_KEY);
  if (!label) {
    label = `${navigator.platform || "Browser"} - ${navigator.userAgent.includes("Edg/") ? "Edge" : navigator.userAgent.includes("Chrome/") ? "Chrome" : "Browser"}`;
    localStorage.setItem(DESKTOP_NOTIFICATION_DEVICE_KEY, label);
  }
  return label;
}

async function enableDesktopNotifications() {
  if (!desktopNotificationsSupported()) return toast("Desktop notifications require a supported browser over HTTPS.");
  const config = desktopNotificationConfig || await loadDesktopNotificationConfig();
  if (!config?.supported || !config.publicKey) return toast("Desktop notifications are not configured on the server.");
  if (!(await confirmDesktopNotificationOptIn())) return;
  const permission = await Notification.requestPermission();
  if (permission !== "granted") {
    openNotifications();
    return toast(permission === "denied" ? "Notifications are blocked in browser site settings." : "Notification permission was not granted.");
  }
  try {
    const registration = await registerDesktopNotificationWorker();
    let subscription = await registration.pushManager.getSubscription();
    if (!subscription) {
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(config.publicKey),
      });
    }
    await apiJson("/api/notifications/subscribe", {
      method: "POST",
      body: JSON.stringify({ subscription: subscription.toJSON(), deviceLabel: desktopNotificationDeviceLabel() }),
    });
    await apiJson("/api/notifications/preferences", { method: "PUT", body: JSON.stringify({ desktop_enabled: true }) });
    currentDeviceSubscribed = true;
    await loadDesktopNotificationConfig(true);
    openNotifications();
    toast("Desktop notifications enabled on this device.");
  } catch (error) {
    toast(error.message || "Unable to enable desktop notifications.");
  }
}

function confirmDesktopNotificationOptIn() {
  return new Promise((resolve) => {
    document.querySelector("#desktopPermissionBackdrop")?.remove();
    const backdrop = document.createElement("div");
    backdrop.id = "desktopPermissionBackdrop";
    backdrop.className = "desktop-permission-backdrop";
    backdrop.innerHTML = `
      <section class="desktop-permission-dialog" role="dialog" aria-modal="true" aria-labelledby="desktopPermissionTitle">
        <div class="desktop-permission-icon" aria-hidden="true">&#128276;</div>
        <div>
          <h3 id="desktopPermissionTitle">Enable Desktop Notifications?</h3>
          <p>Enable desktop notifications to receive important file assignments, corrections, approvals, messages, and due-date alerts even when you are working in another browser tab.</p>
        </div>
        <div class="desktop-permission-actions">
          <button class="mini-button" data-choice="later" type="button">Not Now</button>
          <button class="mini-button desktop-enable-button" data-choice="enable" type="button">Enable Notifications</button>
        </div>
      </section>`;
    const finish = (accepted) => { backdrop.remove(); resolve(accepted); };
    backdrop.addEventListener("click", (event) => {
      const choice = event.target.closest("[data-choice]")?.dataset.choice;
      if (choice) finish(choice === "enable");
      else if (event.target === backdrop) finish(false);
    });
    document.body.appendChild(backdrop);
    backdrop.querySelector('[data-choice="enable"]')?.focus();
  });
}

async function deactivateDesktopSubscription(options = {}) {
  if (!("serviceWorker" in navigator)) return;
  try {
    const registration = desktopServiceWorkerRegistration || await navigator.serviceWorker.getRegistration("/");
    const subscription = await registration?.pushManager?.getSubscription();
    if (!subscription) return;
    if (apiToken()) {
      await apiJson("/api/notifications/subscribe", {
        method: "DELETE",
        body: JSON.stringify({ endpoint: subscription.endpoint }),
      });
    }
    if (options.unsubscribe) await subscription.unsubscribe();
    currentDeviceSubscribed = false;
  } catch (error) {
    console.warn("Desktop subscription cleanup failed", error);
  }
}

async function disableDesktopNotifications() {
  await deactivateDesktopSubscription({ unsubscribe: true });
  try {
    await loadDesktopNotificationConfig(true);
    openNotifications();
    toast("Desktop notifications disabled on this device.");
  } catch (error) {
    toast(error.message || "Unable to disable desktop notifications.");
  }
}

function openDesktopNotificationTarget(notification = {}) {
  const route = new URL(notification.route || "/?page=dashboard", location.origin);
  const page = route.searchParams.get("page") || "dashboard";
  const fileViews = {
    "file-list": "",
    "active-files": "active",
    "fee-pending": "feePending",
    "correction-required": "correctionRequired",
    "correction-required-files": "correctionRequired",
    "not-checked": "notChecked",
    "not-checked-files": "notChecked",
    "completed-files": "completed",
  };
  closeOverlays();
  if (page === "my-task") {
    activePage = "files";
    resetFilters();
    state.filters.listView = "active";
    state.filters.dashboardKind = "myTask";
  } else if (page in fileViews) {
    activePage = "files";
    resetFilters();
    state.filters.listView = fileViews[page];
  } else {
    activePage = ["dashboard", "files", "expenses", "visitors", "dailyReport"].includes(page) ? page : "dashboard";
  }
  const notificationId = String(notification.id || "");
  const related = allNotificationItems().filter((item) =>
    item.id === notificationId || item.id === `file-change-${notificationId.replace(/^file-/, "")}` || (notification.relatedRecordId && item.fileId === notification.relatedRecordId));
  if (related.length) markNotificationItemsRead(related);
  saveTabSession();
  renderAll();
  if (route.searchParams.has("chat")) openTeamChat();
}

function localDesktopStorageKey(key) {
  const userKey = String(state.session?.authUserId || state.session?.userId || state.session?.userEmail || state.currentUser || "guest")
    .toLowerCase()
    .replace(/[^a-z0-9@._-]+/g, "-");
  return `${key}-${userKey}`;
}

function readLocalDesktopSentIds() {
  try {
    return new Set(JSON.parse(localStorage.getItem(localDesktopStorageKey(DESKTOP_LOCAL_SENT_KEY)) || "[]"));
  } catch {
    return new Set();
  }
}

function writeLocalDesktopSentIds(ids) {
  try {
    localStorage.setItem(localDesktopStorageKey(DESKTOP_LOCAL_SENT_KEY), JSON.stringify([...ids].slice(-400)));
  } catch (error) {
    console.warn("Unable to save local desktop notification history", error);
  }
}

function localDesktopAlertsEnabled() {
  return desktopNotificationsSupported()
    && Notification.permission === "granted"
    && desktopNotificationConfig?.preferences?.desktop_enabled
    // A subscribed device receives the same event through Web Push. Showing it
    // here as well creates a second Windows notification when the page is open.
    && !currentDeviceSubscribed;
}

function desktopNotificationRouteForItem(item = {}) {
  if (item.chatId) return `/?page=dashboard&chat=${encodeURIComponent(item.chatId)}`;
  if (item.category === "billing") return `/?page=fee-pending&file=${encodeURIComponent(item.fileId || "")}`;
  if (item.category === "corrections") return `/?page=correction-required-files&file=${encodeURIComponent(item.fileId || "")}`;
  if (item.type === "Awaiting Checking" || item.category === "checking") return `/?page=not-checked-files&file=${encodeURIComponent(item.fileId || "")}`;
  if (item.category === "assignments") return `/?page=my-task&file=${encodeURIComponent(item.fileId || "")}`;
  if (item.fileId) return `/?page=active-files&file=${encodeURIComponent(item.fileId)}`;
  return "/?page=dashboard";
}

function desktopNotificationBelongsToCurrentUser(item = {}) {
  const user = loggedInUser();
  if (!user) return false;
  if (item.targetUserId || item.targetUserEmail || item.targetUserName) {
    return sameUserIdentity(user, item.targetUserId, item.targetUserEmail, item.targetUserName)
      || sameStaffName(item.targetUserName, state.currentUser);
  }
  if (!item.fileId || !["assignments", "due"].includes(item.category)) return false;
  const file = (state.files || []).find((row) => row.id === item.fileId);
  return Boolean(file && currentFileBelongsToUser(file, user));
}

function showLocalDesktopNotification(item = {}) {
  if (!("Notification" in window) || Notification.permission !== "granted") return false;
  const title = cleanTextForNotification(item.title || item.type || "CA File Tracker", 80);
  const body = cleanTextForNotification(item.text || "You have a new CA File Tracker update.", 180);
  const route = desktopNotificationRouteForItem(item);
  try {
    const notification = new Notification(title, {
      body,
      icon: "/assets/ca-india-logo.png",
      badge: "/assets/ca-india-logo.png",
      tag: item.id || `${title}-${body}`,
      renotify: false,
      data: { id: item.id || "", route, relatedRecordId: item.fileId || "" },
    });
    notification.onclick = () => {
      window.focus();
      openDesktopNotificationTarget(notification.data || {});
      notification.close();
    };
    return true;
  } catch (error) {
    console.warn("Local desktop notification failed", error);
    return false;
  }
}

function cleanTextForNotification(value, max = 180) {
  return String(value || "").replace(/[\r\n\t]+/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
}

function dispatchLocalDesktopNotifications() {
  if (!state.session?.loggedIn || !localDesktopAlertsEnabled()) return;
  const baselineKey = localDesktopStorageKey(DESKTOP_LOCAL_BASELINE_KEY);
  let baseline = 0;
  try {
    baseline = Number(localStorage.getItem(baselineKey) || 0);
  } catch (error) {
    console.warn("Unable to read local desktop notification baseline", error);
  }
  if (!baseline) {
    try {
      localStorage.setItem(baselineKey, String(Date.now()));
    } catch (error) {
      console.warn("Unable to save local desktop notification baseline", error);
    }
    return;
  }
  const sent = readLocalDesktopSentIds();
  const dueNow = allNotificationItems()
    .filter((item) => !item.isRead && item.id && !sent.has(item.id))
    .filter((item) => notificationItemTime(item) >= baseline)
    .filter(desktopNotificationBelongsToCurrentUser)
    .slice(0, 3);
  if (!dueNow.length) return;
  dueNow.forEach((item) => {
    if (showLocalDesktopNotification(item)) sent.add(item.id);
  });
  writeLocalDesktopSentIds(sent);
}

async function sendLocalDesktopTestNotification() {
  if (!desktopNotificationsSupported()) {
    toast("Desktop notifications need HTTPS and a supported browser like Edge or Chrome.");
    return false;
  }
  if (Notification.permission !== "granted") {
    const permission = await Notification.requestPermission();
    if (permission !== "granted") {
      toast(permission === "denied" ? "Notifications are blocked in browser site settings." : "Notification permission was not granted.");
      return false;
    }
  }
  return showLocalDesktopNotification({
    id: `local-test-${Date.now()}`,
    title: "CA File Tracker",
    text: "Desktop notifications are working on this device.",
    category: "system",
    createdAt: Date.now(),
  });
}

async function applyDesktopNotificationRouteFromLocation() {
  const params = new URLSearchParams(location.search);
  if (!params.has("page") && !params.has("chat") && !params.has("file")) return;
  openDesktopNotificationTarget({
    route: `${location.pathname}${location.search}`,
    relatedRecordId: params.get("file") || "",
  });
  history.replaceState({}, "", location.pathname);
}

function perfStart() {
  return PERF_LOG_ENABLED && window.performance ? performance.now() : 0;
}

function perfLog(label, startedAt, details = {}) {
  if (!PERF_LOG_ENABLED || !startedAt || !window.performance) return;
  console.info(`[perf] ${label}: ${Math.round(performance.now() - startedAt)}ms`, details);
}

async function backendApiJson(path, options = {}) {
  const startedAt = perfStart();
  const { skipAuthRefresh = false, ...requestOptions } = options;
  const headers = {
    "Content-Type": "application/json",
    ...(requestOptions.headers || {}),
  };
  const token = apiToken();
  if (token) headers.Authorization = `Bearer ${token}`;
  const response = await fetch(path, {
    ...requestOptions,
    headers,
  });
  const payload = await response.json().catch(() => ({}));
  if (response.status === 401 && path !== "/api/auth/login" && path !== "/api/auth/refresh" && !skipAuthRefresh) {
    const refreshed = await refreshApiSession();
    if (refreshed) return backendApiJson(path, { ...options, skipAuthRefresh: true });
  }
  if (!response.ok) {
    const error = new Error(payload.error || "Server request failed.");
    error.status = response.status;
    error.payload = payload;
    throw error;
  }
  perfLog("api", startedAt, { path, method: requestOptions.method || "GET" });
  return payload;
}

async function refreshApiSession() {
  const refreshToken = sessionStorage.getItem(API_REFRESH_TOKEN_KEY);
  if (!refreshToken) return false;
  try {
    const payload = await backendApiJson("/api/auth/refresh", {
      method: "POST",
      body: JSON.stringify({ refreshToken }),
      skipAuthRefresh: true,
    });
    if (!payload.session?.access_token) return false;
    setApiSession(payload.session);
    sessionStorage.setItem(API_MODE_KEY, "supabase");
    return true;
  } catch (error) {
    console.warn("Session refresh failed", error);
    setApiSession(null);
    sessionStorage.removeItem(API_MODE_KEY);
    return false;
  }
}

async function saveStateToApi() {
  if (!isSupabaseMode()) return;
  const shared = sharedStateForStorage(state);
  const snapshot = JSON.stringify(shared);
  if (snapshot === lastRemoteSaveSnapshot) return;
  clearTimeout(remoteSaveTimer);
  remoteSaveTimer = setTimeout(async () => {
    try {
      await apiJson("/api/state", {
        method: "PUT",
        body: JSON.stringify({ state: shared }),
      });
      lastRemoteSaveSnapshot = snapshot;
    } catch (error) {
      console.warn("Central database save failed", error);
    }
  }, 700);
}

async function saveFileToApi(file) {
  if (!isSupabaseMode() || !file?.id) return;
  try {
    return await apiJson(`/api/files/${encodeURIComponent(file.id)}`, {
      method: "PUT",
      body: JSON.stringify({ file }),
    });
  } catch (error) {
    console.warn("Central file save failed", error);
    throw error;
  }
}

async function deleteFileFromApi(fileId) {
  if (!isSupabaseMode() || !fileId) return;
  return apiJson(`/api/files/${encodeURIComponent(fileId)}`, { method: "DELETE" });
}

async function syncFileRecordToApi(file) {
  const startedAt = perfStart();
  const result = await saveFileToApi(file);
  if (result?.file) {
    const existingIndex = (state.files || []).findIndex((item) => item.id === result.file.id);
    state.files = existingIndex >= 0
      ? state.files.map((item) => (item.id === result.file.id ? { ...item, ...result.file } : item))
      : [result.file, ...(state.files || [])];
  } else if (result?.files) {
    state.files = result.files;
  }
  if (result?.fileNotifications) state.fileNotifications = mergeFileNotifications(state.fileNotifications || [], result.fileNotifications).slice(0, 500);
  saveState({ skipMerge: true, skipRemote: true });
  perfLog("file sync", startedAt, { fileId: file?.id, notifications: result?.fileNotifications?.length || 0 });
  return result;
}

