function fileSerialNumber(file, fallbackIndex = 0) {
  return fallbackIndex + 1;
}

function fileRowActions(file) {
  if (state.filters.listView === "billed" && isBilledFile(file)) return billedFileActions(file);
  const actions = [`<button class="mini-button" data-edit="${file.id}">Edit</button>`];
  const canManageBilling = rolePerm().assign;
  const canManageFeeReceipt = ["Admin", "Manager"].includes(normalizeRole(state.currentRole));
  if (canManageBilling && state.filters.listView === "completed" && isBillingReadyFile(file) && !isNonBilledFile(file)) {
    actions.push(`<button class="mini-button ${file.billingType === "Non-Billable" ? "success" : ""}" data-non-billable="${file.id}">Non-Billable</button>`);
    if (!file.billed) actions.push(`<button class="mini-button success" data-mark-billed="${file.id}">Billed</button>`);
  }
  if (canManageBilling && state.filters.listView === "nonBilled" && isNonBilledFile(file)) {
    if (file.billingType === "Non-Billable") {
      actions.push(`<button class="mini-button success" data-billable="${file.id}">Mark Billable</button>`);
    } else {
      actions.push(`<button class="mini-button success" data-mark-billed="${file.id}">Billed</button>`);
    }
  }
  if (canManageBilling && state.filters.listView === "billed" && isBilledFile(file)) {
    actions.push(`<button class="mini-button" data-fee-non-billable="${file.id}">Non-Billable</button>`);
    if (file.billed && !file.feeReceived) actions.push(`<button class="mini-button success" data-mark-received="${file.id}">Mark Received</button>`);
  }
  if (canManageFeeReceipt && ["billed", "feeReceived"].includes(state.filters.listView) && file.billed && file.feeReceived) {
    const linkedCollection = linkedFeeReceiptCollection(file);
    if (linkedCollection) {
      actions.push(`<button class="mini-button" data-go-fee-transaction="${linkedCollection.id}">Go Transaction</button>`);
    } else {
      actions.push(`<button class="mini-button" data-mark-not-received="${file.id}">Not Received</button>`);
    }
  }
  if (canManageBilling && state.filters.listView === "feePending" && isFeePendingFile(file)) {
    actions.push(`<button class="mini-button" data-fee-non-billable="${file.id}">Non-Billable</button>`);
    actions.push(`<button class="mini-button success" data-mark-received="${file.id}">Mark Received</button>`);
  }
  if (file.feeReceived && ["billed", "feeReceived"].includes(state.filters.listView)) {
    actions.push(`<span class="badge filed">Received</span>`);
  }
  if (rolePerm().delete) actions.push(`<button class="mini-button danger" data-delete="${file.id}">Delete</button>`);
  return actions.join("");
}

function billedActionIcon(name) {
  const paths = {
    edit: `<path d="M4 13.5V16h2.5L14 8.5 11.5 6 4 13.5Z"/><path d="m10.5 7 2.5 2.5"/>`,
    received: `<path d="m4 10 3 3 7-7"/>`,
    transaction: `<path d="M3 6h12M3 10h12M3 14h8"/>`,
    nonbillable: `<circle cx="9" cy="9" r="6"/><path d="m5 13 8-8"/>`,
    reverse: `<path d="M5 6H2v-3"/><path d="M2.5 6a7 7 0 1 1 .5 7"/>`,
    delete: `<path d="M3 5h12M7 5V3h4v2M5 5l1 11h6l1-11M8 8v5M10 8v5"/>`,
    menu: `<circle cx="9" cy="4" r="1" fill="currentColor" stroke="none"/><circle cx="9" cy="9" r="1" fill="currentColor" stroke="none"/><circle cx="9" cy="14" r="1" fill="currentColor" stroke="none"/>`,
  };
  return `<svg class="billed-action-icon" viewBox="0 0 18 18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name] || paths.menu}</svg>`;
}

function billedActionMenuItem({ label, icon, attrs = "", danger = false, divider = false }) {
  return `${divider ? `<div class="billed-action-menu-divider" role="separator"></div>` : ""}<button type="button" class="billed-action-menu-item${danger ? " danger" : ""}" role="menuitem" ${attrs}>${billedActionIcon(icon)}<span>${escapeHtml(label)}</span></button>`;
}

function billedFileActions(file = {}, options = {}) {
  const summary = feeReceiptSummaryForFile(file);
  const activeReceipt = summary.receipts[0] || null;
  const linkedCollection = linkedFeeReceiptCollection(file) || (activeReceipt ? linkedCollectionForFeeReceipt(activeReceipt) : null);
  const hasReceivedAmount = summary.totalReceived > 0 || summary.totalDiscount > 0;
  const isSettled = hasReceivedAmount && summary.outstandingAmount <= 0;
  const canEdit = Boolean(rolePerm().edit);
  const canManageBilling = Boolean(rolePerm().assign);
  const canManageReceipt = ["Admin", "Manager"].includes(normalizeRole(state.currentRole));
  const canDelete = Boolean(rolePerm().delete);
  const fileId = escapeHtml(file.id || "");
  const menuItems = [];
  const feePendingContext = options.context === "feePending";
  const receiveLabel = hasReceivedAmount ? "Receive Balance" : "Mark Received";

  if (canEdit) menuItems.push(billedActionMenuItem({ label: "Edit", icon: "edit", attrs: `data-edit="${fileId}"` }));
  if (canManageBilling && !hasReceivedAmount && !activeReceipt && !linkedCollection) menuItems.push(billedActionMenuItem({ label: "Mark Non-Billable", icon: "nonbillable", attrs: `data-fee-non-billable="${fileId}"` }));
  if (canManageReceipt && linkedCollection?.id) menuItems.push(billedActionMenuItem({ label: "View Transaction", icon: "transaction", attrs: `data-go-fee-transaction="${escapeHtml(linkedCollection.id)}"` }));
  if (canManageBilling && summary.outstandingAmount > 0) menuItems.push(billedActionMenuItem({ label: feePendingContext ? receiveLabel : "Mark Received", icon: "received", attrs: `data-mark-received="${fileId}"` }));
  if (canManageReceipt && activeReceipt?.id) menuItems.push(billedActionMenuItem({ label: "Mark Not Received", icon: "reverse", attrs: `data-fee-receipt-not-received="${escapeHtml(activeReceipt.id)}"` }));
  else if (canManageReceipt && hasReceivedAmount && !linkedCollection) menuItems.push(billedActionMenuItem({ label: "Mark Not Received", icon: "reverse", attrs: `data-mark-not-received="${fileId}"` }));
  if (canManageReceipt && summary.outstandingAmount > 0 && !linkedCollection) menuItems.push(billedActionMenuItem({ label: "Go to Transactions", icon: "transaction", attrs: `data-go-transactions="${fileId}"` }));
  if (canDelete) {
    menuItems.push(billedActionMenuItem({ label: "Delete", icon: "delete", attrs: `data-delete-billed="${fileId}"`, danger: true, divider: true }));
  }

  let primaryAction = "";
  if (linkedCollection?.id && canManageReceipt) {
    primaryAction = `<button type="button" class="billed-primary-action transaction" data-go-fee-transaction="${escapeHtml(linkedCollection.id)}">${billedActionIcon("transaction")}<span>View Transaction</span></button>`;
  } else if (summary.outstandingAmount > 0 && canManageBilling) {
    primaryAction = `<button type="button" class="billed-primary-action mark-received" data-mark-received="${fileId}">${billedActionIcon("received")}<span>${escapeHtml(feePendingContext ? receiveLabel : "Mark Received")}</span></button>`;
  } else if (isSettled || hasReceivedAmount) {
    primaryAction = `<button type="button" class="billed-primary-action received" data-billed-receipt-details="${fileId}">${billedActionIcon("received")}<span>Received</span></button>`;
  } else if (canEdit) {
    primaryAction = `<button type="button" class="billed-primary-action view-only" data-edit="${fileId}">${billedActionIcon("edit")}<span>View File</span></button>`;
  } else {
    primaryAction = `<span class="billed-payment-state">${isSettled || hasReceivedAmount ? "Received" : "Pending"}</span>`;
  }

  return `<div class="billed-actions" data-billed-actions="${fileId}">
    ${primaryAction}
    ${menuItems.length ? `<button type="button" class="billed-menu-toggle" data-billed-menu-toggle="${fileId}" aria-label="Open actions for ${escapeHtml(file.name || "file")}" aria-haspopup="menu" aria-expanded="false">${billedActionIcon("menu")}</button>
    <div class="billed-action-menu" data-billed-action-menu="${fileId}" role="menu" aria-label="Actions for ${escapeHtml(file.name || "file")}">${menuItems.join("")}</div>` : ""}
  </div>`;
}

let activeBilledActionToggle = null;
let activeBilledActionMenu = null;
let activeBilledActionOwner = null;
let billedActionMenuDocumentBound = false;
let billedActionPositionFrame = 0;

function closeBilledActionMenus({ restoreFocus = false } = {}) {
  const toggle = activeBilledActionToggle;
  const menu = activeBilledActionMenu;
  if (billedActionPositionFrame) cancelAnimationFrame(billedActionPositionFrame);
  billedActionPositionFrame = 0;
  if (menu) {
    menu.classList.remove("open", "open-up");
    menu.style.removeProperty("top");
    menu.style.removeProperty("left");
    if (activeBilledActionOwner?.isConnected) activeBilledActionOwner.appendChild(menu);
    else menu.remove();
  }
  toggle?.setAttribute("aria-expanded", "false");
  if (restoreFocus && toggle?.isConnected) toggle.focus();
  activeBilledActionToggle = null;
  activeBilledActionMenu = null;
  activeBilledActionOwner = null;
}

function positionBilledActionMenu() {
  const toggle = activeBilledActionToggle;
  const menu = activeBilledActionMenu;
  if (!toggle?.isConnected || !menu?.isConnected) return closeBilledActionMenus();
  if (window.matchMedia("(max-width: 680px)").matches) {
    menu.classList.remove("open-up");
    menu.style.removeProperty("top");
    menu.style.removeProperty("left");
    return;
  }
  const anchor = toggle.getBoundingClientRect();
  const menuBox = menu.getBoundingClientRect();
  const openUp = window.innerHeight - anchor.bottom < menuBox.height + 12 && anchor.top > menuBox.height + 12;
  menu.classList.toggle("open-up", openUp);
  menu.style.top = `${Math.max(8, openUp ? anchor.top - menuBox.height - 6 : anchor.bottom + 6)}px`;
  menu.style.left = `${Math.max(8, Math.min(anchor.right - menuBox.width, window.innerWidth - menuBox.width - 8))}px`;
}

function scheduleBilledActionMenuPosition() {
  if (!activeBilledActionMenu || billedActionPositionFrame) return;
  billedActionPositionFrame = requestAnimationFrame(() => {
    billedActionPositionFrame = 0;
    positionBilledActionMenu();
  });
}

function openBilledActionMenu(toggle, { focusFirst = false } = {}) {
  const owner = toggle.closest(".billed-actions");
  const menu = activeBilledActionToggle === toggle && activeBilledActionMenu
    ? activeBilledActionMenu
    : owner?.querySelector("[data-billed-action-menu]");
  if (!menu) return;
  if (activeBilledActionToggle === toggle && activeBilledActionMenu === menu) {
    closeBilledActionMenus();
    return;
  }
  closeBilledActionMenus();
  activeBilledActionToggle = toggle;
  activeBilledActionMenu = menu;
  activeBilledActionOwner = owner;
  document.body.appendChild(menu);
  menu.classList.add("open");
  toggle.setAttribute("aria-expanded", "true");
  positionBilledActionMenu();
  if (focusFirst) menu.querySelector(".billed-action-menu-item")?.focus();
}

function bindBilledActionMenus() {
  if (billedActionMenuDocumentBound) return;
  billedActionMenuDocumentBound = true;
  document.addEventListener("click", (event) => {
    if (event.target.closest("[data-billed-menu-toggle]")) return;
    if (event.target.closest(".billed-action-menu-item")) return closeBilledActionMenus();
    if (!event.target.closest(".billed-action-menu")) closeBilledActionMenus();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") return closeBilledActionMenus({ restoreFocus: true });
    const toggle = event.target.closest("[data-billed-menu-toggle]");
    if (toggle && event.key === "ArrowDown") {
      event.preventDefault();
      event.stopPropagation();
      openBilledActionMenu(toggle, { focusFirst: true });
      return;
    }
    const item = event.target.closest(".billed-action-menu-item");
    if (!item || !["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const menu = item.closest(".billed-action-menu");
    const items = [...menu.querySelectorAll(".billed-action-menu-item:not(:disabled)")];
    if (!items.length) return;
    event.preventDefault();
    const current = items.indexOf(item);
    const next = event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : event.key === "ArrowDown" ? (current + 1) % items.length : (current - 1 + items.length) % items.length;
    items[next].focus();
  });
  document.addEventListener("scroll", scheduleBilledActionMenuPosition, true);
  window.addEventListener("resize", scheduleBilledActionMenuPosition);
}

function feeReceiptById(receiptId) {
  return (state.feeReceipts || []).find((receipt) => receipt.id === receiptId) || null;
}

function feeReceiptFile(receipt = {}) {
  const fileId = receipt.fileId || receipt.file_id || "";
  return (state.files || []).find((file) => file.id === fileId) || null;
}

function closeFeeReceiptActionModal() {
  document.querySelector("#feeReceiptActionModal")?.remove();
  if (!document.querySelector(".drawer.open") && !document.querySelector(".notification-panel.open")) {
    document.querySelector("#backdrop")?.classList.remove("show");
  }
}

function feeReceiptAuditDetails(receipt = {}, file = {}) {
  const pushedBefore = receiptWasPushed(receipt);
  return [
    ["Client Name", file.name || "-"],
    ["Service Type", file.serviceType || "-"],
    ["FY", fileFy(file) || "-"],
    ["Bill Amount", rupee(dashboardFileAmount(file, "billed"))],
    ["Original Receipt Date", displayDate(feeReceiptRecordDate(receipt))],
    ["Original Received Amount", rupee(receipt.amount || receipt.receivedAmount || receipt.received_amount || 0)],
    ["Payment Mode", receipt.paymentMode || receipt.payment_mode || "-"],
    ["Payment Account", financeAccountLabel(transactionAccountKey(receipt, ""))],
    ["Receipt Status", feeReceiptRecordStatus(receipt)],
    ["Previous Transaction Push Status", pushedBefore ? "Pushed" : "Not pushed"],
    ["Linked Transaction Status", receipt.linkedTransactionStatus || receipt.linked_transaction_status || (linkedCollectionForFeeReceipt(receipt) ? "Active" : "-")],
    ["Reversal Date", receipt.reversedAt || receipt.reversed_at ? formatDateTime(receipt.reversedAt || receipt.reversed_at) : "-"],
    ["Reversed By", receipt.reversedBy || receipt.reversed_by || "-"],
    ["Reversal Reason", receipt.reversalReason || receipt.reversal_reason || "-"],
  ];
}

function feeReceiptAmountDetails(receipt = {}, file = {}) {
  const billedAmount = Number(dashboardFileAmount(file, "billed") || 0);
  const receivedAmount = Number(receipt.amount ?? receipt.receivedAmount ?? receipt.received_amount ?? 0);
  const discountAmount = Number(receipt.discountAmount ?? receipt.discount_amount ?? receipt.discount ?? 0);
  const savedBalance = receipt.balanceAmount ?? receipt.balance_amount;
  const balanceAmount = savedBalance === undefined || savedBalance === null
    ? Math.max(0, billedAmount - receivedAmount - discountAmount)
    : Number(savedBalance || 0);
  return [
    ["Billed Amount", rupee(billedAmount)],
    ["Received Amount", rupee(receivedAmount)],
    ["Discount Amount", rupee(discountAmount)],
    ["Balance Amount", rupee(balanceAmount)],
  ];
}

