async function confirmFeeReceiptNotReceived(receiptId) {
  const reason = String(document.querySelector("#feeReceiptReversalReason")?.value || "").trim();
  if (!reason) return toast("Reason for marking the receipt as Not Received is required.");
  const button = document.querySelector("#confirmFeeReceiptNotReceived");
  if (button) button.disabled = true;
  try {
    if (isSupabaseMode()) {
      await markFeeReceiptNotReceivedToApi(receiptId, reason);
    } else {
      reverseFeeReceiptLocally(receiptId, reason);
    }
    closeFeeReceiptActionModal();
    toast("Fee receipt marked as Not Received. Outstanding fee and linked balances were recalculated.");
    renderAll();
  } catch (error) {
    if (button) button.disabled = false;
    toast(error.message || "Unable to mark this fee receipt as Not Received.");
  }
}

function reverseFeeReceiptLocally(receiptId, reason) {
  const receipt = feeReceiptById(receiptId);
  const file = feeReceiptFile(receipt || {});
  if (!receipt || !file || !isValidFeeReceiptRecord(receipt)) throw new Error("This fee receipt cannot be reversed.");
  const now = new Date().toISOString();
  const actor = state.currentUser || loggedInUser()?.name || "";
  state.feeReceipts = (state.feeReceipts || []).map((item) => item.id === receiptId ? {
    ...item,
    status: "not_received",
    receiptStatus: "not_received",
    receipt_status: "not_received",
    isReversed: true,
    is_reversed: true,
    reversedAt: now,
    reversed_at: now,
    reversedBy: actor,
    reversed_by: actor,
    reversalReason: reason,
    reversal_reason: reason,
    previousPushStatus: receiptWasPushed(item) ? "pushed" : "not_pushed",
    linkedTransactionStatus: receiptWasPushed(item) ? "reversed" : "not_applicable",
  } : item);
  state.otherCashCollections = (state.otherCashCollections || []).map((item) => {
    const linked = item.id === (receipt.transactionId || receipt.transaction_id)
      || item.feeReceiptId === receiptId || item.fee_receipt_id === receiptId
      || item.sourceId === receiptId || item.source_id === receiptId;
    return linked ? { ...item, status: "reversed", reversed: true, isReversed: true, is_reversed: true, reversedAt: now, reversalReason: reason } : item;
  });
  const summary = feeReceiptSummaryForFile(file);
  const latest = summary.receipts[0] || {};
  const fileIndex = state.files.findIndex((item) => item.id === file.id);
  state.files[fileIndex] = {
    ...file,
    billed: true,
    billingType: "Billable",
    feeReceived: summary.billedAmount > 0 && summary.totalReceived >= summary.billedAmount,
    feeReceivedAmount: summary.totalReceived,
    amountReceived: summary.totalReceived,
    amount_received: summary.totalReceived,
    balanceAmount: summary.outstandingAmount,
    balance_amount: summary.outstandingAmount,
    feeReceivedDate: summary.latestReceiptDate,
    paymentStatus: summary.totalReceived <= 0 ? "Fee Not Received" : (summary.outstandingAmount > 0 ? "Partly Received" : "Fee Received"),
    feeReceiptId: latest.id || "",
    fee_receipt_id: latest.id || "",
    feeTransactionId: latest.transactionId || latest.transaction_id || "",
    fee_transaction_id: latest.transactionId || latest.transaction_id || "",
    updatedAt: Date.now(),
  };
  addAuditLog("Fee receipt marked Not Received", { fileId: file.id, receiptId, reason });
  saveState();
}

function notCheckedFileActions(file) {
  const actions = [`<button class="mini-button" data-edit="${file.id}">${canManageChecking() ? "View" : "Edit"}</button>`];
  if (canManageChecking()) {
    if (canCheckFile(file)) {
      actions.push(`<button class="mini-button success" data-check-file="${file.id}">Check File</button>`);
    } else {
      actions.push(`<span class="subtext own-check-blocked">You cannot check a file completed by yourself. This file must be checked by another authorised user.</span>`);
    }
    actions.push(`<button class="mini-button danger" data-return-correction="${file.id}">Return for Correction</button>`);
  }
  return actions.join("");
}

function removeBilledFileLocally(fileId, removalReason) {
  const index = (state.files || []).findIndex((file) => file.id === fileId);
  if (index < 0) throw new Error("File record not found.");
  const before = { ...state.files[index] };
  const now = new Date().toISOString();
  const actor = state.currentUser || loggedInUser()?.name || "Team";
  const receiptIds = new Set(
    (state.feeReceipts || [])
      .filter((receipt) => (receipt.fileId || receipt.file_id) === fileId && isValidFeeReceiptRecord(receipt))
      .map((receipt) => receipt.id),
  );
  const transactionIds = new Set(
    (state.feeReceipts || [])
      .filter((receipt) => receiptIds.has(receipt.id))
      .map((receipt) => receipt.transactionId || receipt.transaction_id)
      .filter(Boolean),
  );
  state.feeReceipts = (state.feeReceipts || []).map((receipt) => receiptIds.has(receipt.id) ? {
    ...receipt,
    status: "not_received",
    receiptStatus: "not_received",
    receipt_status: "not_received",
    isReversed: true,
    is_reversed: true,
    reversedAt: now,
    reversed_at: now,
    reversedBy: actor,
    reversed_by: actor,
    reversalReason: removalReason,
    reversal_reason: removalReason,
    linkedTransactionStatus: transactionIds.has(receipt.transactionId || receipt.transaction_id) ? "reversed" : "not_applicable",
  } : receipt);
  state.otherCashCollections = (state.otherCashCollections || []).map((collection) => {
    const linked = transactionIds.has(collection.id)
      || receiptIds.has(collection.feeReceiptId || collection.fee_receipt_id || collection.sourceId || collection.source_id)
      || ((collection.fileId || collection.file_id) === fileId && (collection.sourceType || collection.source_type) === "fee_receipt");
    return linked ? { ...collection, status: "reversed", reversed: true, isReversed: true, is_reversed: true, reversedAt: now, reversed_at: now, reversedBy: actor, reversalReason: removalReason } : collection;
  });
  state.files[index] = {
    ...before,
    status: "Removed",
    workflowStatus: "Removed",
    stages: { ...normalizeStages(before), Removed: true },
    isRemoved: true,
    is_removed: true,
    removedAt: now,
    removed_at: now,
    removedBy: actor,
    removalReason,
    removal_reason: removalReason,
    previousStatus: "Billed",
    previous_status: "Billed",
    updatedAt: Date.now(),
    lastUpdatedDate: todayDate(),
  };
  addAuditLog("Billed file safely removed", {
    fileId,
    clientName: before.name || "",
    serviceType: before.serviceType || "",
    actionPerformed: "Reverse financial links and move to Removed Files",
    previousValue: { billed: before.billed, feeReceived: before.feeReceived, billAmount: dashboardFileAmount(before, "billed") },
    newValue: { status: "Removed", receiptsReversed: receiptIds.size, transactionsReversed: transactionIds.size },
    removalReason,
  });
  saveState({ skipMerge: true });
}

async function deleteBilledFileSafely(fileId, button = null) {
  if (!rolePerm().delete || !["Admin", "Manager"].includes(normalizeRole(state.currentRole))) return toast("Only Admin or an authorised Manager can delete billed records.");
  const file = (state.files || []).find((item) => item.id === fileId);
  if (!file) return toast("File record not found.");
  const billNo = file.billNo || file.bill_number || file.invoiceNumber || file.invoiceNo || "-";
  const summary = feeReceiptSummaryForFile(file);
  const message = `Remove this billed record safely?\n\nClient: ${file.name || "-"}\nService: ${file.serviceType || "-"}\nBill No.: ${billNo}\nBilled Amount: ${rupee(summary.billedAmount)}\nReceived Amount: ${rupee(summary.totalReceived)}\nOutstanding Balance: ${rupee(summary.outstandingAmount)}\n\nActive receipts and linked transactions will be reversed, and the file will move to Removed Files with its audit history preserved.`;
  if (!window.confirm(message)) return;
  const originalHtml = button?.innerHTML || "";
  if (button) {
    button.disabled = true;
    button.classList.add("is-loading");
    button.innerHTML = `<span class="billed-action-spinner" aria-hidden="true"></span><span>Removing...</span>`;
  }
  const removalReason = "Deleted from Billed Files by an authorised user";
  try {
    if (isSupabaseMode()) await removeBilledFileInApi(fileId, removalReason);
    else removeBilledFileLocally(fileId, removalReason);
    closeBilledActionMenus();
    toast("Billed record moved to Removed Files. Linked financial entries were safely reversed.");
    renderAll();
  } catch (error) {
    if (button) {
      button.disabled = false;
      button.classList.remove("is-loading");
      button.innerHTML = originalHtml;
    }
    toast(error.message || "Unable to remove this billed record safely.");
  }
}

function bindFileActions() {
  bindBilledActionMenus();
  document.querySelectorAll("[data-billed-menu-toggle]").forEach((toggle) => {
    toggle.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      openBilledActionMenu(toggle);
    };
  });
  document.querySelectorAll("[data-completed-row-toggle]").forEach((button) => {
    button.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const desktopRow = button.closest(".completed-file-row");
      const mobileCard = button.closest(".completed-mobile-card");
      const details = desktopRow?.nextElementSibling?.classList.contains("completed-details-row")
        ? desktopRow.nextElementSibling
        : mobileCard?.querySelector(".completed-mobile-details");
      if (!details) return;
      const opening = details.hidden;
      details.hidden = !opening;
      button.setAttribute("aria-expanded", String(opening));
      button.classList.toggle("expanded", opening);
    };
  });
  document.querySelectorAll("[data-active-row-toggle]").forEach((button) => {
    button.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const desktopRow = button.closest(".active-file-row");
      const mobileCard = button.closest(".active-mobile-card");
      const details = desktopRow?.nextElementSibling?.classList.contains("active-details-row")
        ? desktopRow.nextElementSibling
        : mobileCard?.querySelector(".active-mobile-details");
      if (!details) return;
      const opening = details.hidden;
      details.hidden = !opening;
      button.setAttribute("aria-expanded", String(opening));
      button.classList.toggle("expanded", opening);
    };
  });
  document.querySelectorAll("[data-master-file-toggle]").forEach((button) => {
    button.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const desktopRow = button.closest(".master-file-row");
      const mobileCard = button.closest(".master-file-mobile-card");
      const details = desktopRow?.nextElementSibling?.classList.contains("master-file-details-row")
        ? desktopRow.nextElementSibling
        : mobileCard?.querySelector(".master-file-mobile-details");
      if (!details) return;
      const opening = details.hidden;
      details.hidden = !opening;
      button.setAttribute("aria-expanded", String(opening));
      button.classList.toggle("expanded", opening);
    };
  });
  document.querySelectorAll("[data-billed-sort]").forEach((button) => {
    button.onclick = () => {
      const key = button.dataset.billedSort;
      billedTableSort = billedTableSort.key === key
        ? { key, direction: billedTableSort.direction === "asc" ? "desc" : "asc" }
        : { key, direction: "asc" };
      renderAll();
    };
  });
  document.querySelectorAll("[data-billed-row-toggle]").forEach((button) => {
    button.onclick = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const desktopRow = button.closest(".billed-file-row");
      const mobileCard = button.closest(".billed-mobile-card");
      const details = desktopRow?.nextElementSibling?.classList.contains("billed-details-row")
        ? desktopRow.nextElementSibling
        : mobileCard?.querySelector(".billed-mobile-details");
      if (!details) return;
      const opening = details.hidden;
      details.hidden = !opening;
      button.setAttribute("aria-expanded", String(opening));
      button.classList.toggle("expanded", opening);
    };
  });
  document.querySelectorAll("[data-edit]").forEach((btn) => (btn.onclick = () => openFileDrawer(btn.dataset.edit)));
  document.querySelectorAll("[data-check-file]").forEach((btn) => {
    btn.onclick = () => checkCompletedFile(btn.dataset.checkFile);
  });
  document.querySelectorAll("[data-return-correction]").forEach((btn) => {
    btn.onclick = () => returnFileForCorrection(btn.dataset.returnCorrection);
  });
  document.querySelectorAll("[data-billable]").forEach((btn) => {
    btn.onclick = () => updateFileBilling(btn.dataset.billable, { billingType: "Billable", billed: false, billedDate: "", feeReceived: false, feeReceivedDate: "" }, "File marked as Billable successfully.");
  });
  document.querySelectorAll("[data-non-billable]").forEach((btn) => {
    btn.onclick = () => updateFileBilling(btn.dataset.nonBillable, { billingType: "Non-Billable", billed: false, billedDate: "", feeReceived: false, feeReceivedDate: "" }, "File marked as non-billable");
  });
  document.querySelectorAll("[data-fee-non-billable]").forEach((btn) => {
    btn.onclick = async () => {
      const file = state.files.find((item) => item.id === btn.dataset.feeNonBillable);
      if (!file) return toast("File record not found.");
      if (["billed", "feePending"].includes(state.filters.listView)) {
        const summary = feeReceiptSummaryForFile(file);
        if (summary.totalReceived > 0 || summary.totalDiscount > 0 || summary.receipts.length || linkedFeeReceiptCollection(file)) {
          return toast("Reverse all receipts and linked transactions before marking this file Non-Billable.");
        }
        if (!window.confirm(`Mark ${file.name || "this file"} (${file.serviceType || "service"}) as Non-Billable? The file and work history will be preserved.`)) return;
        btn.disabled = true;
      }
      const ok = await updateFileBilling(btn.dataset.feeNonBillable, { billingType: "Non-Billable", billed: false, billedDate: "", feeReceived: false, feeReceivedDate: "" }, "File marked as Non Billable.");
      if (!ok && btn.isConnected) btn.disabled = false;
    };
  });
  document.querySelectorAll("[data-mark-billed]").forEach((btn) => {
    btn.onclick = () => openBilledFileModal(btn.dataset.markBilled);
  });
  document.querySelectorAll("[data-mark-received]").forEach((btn) => {
    btn.onclick = () => openMarkReceivedModal(btn.dataset.markReceived);
  });
  document.querySelectorAll("[data-view-fee-receipt]").forEach((btn) => {
    btn.onclick = () => openFeeReceiptViewModal(btn.dataset.viewFeeReceipt);
  });
  document.querySelectorAll("[data-billed-receipt-details]").forEach((btn) => {
    btn.onclick = () => openBilledReceiptDetails(btn.dataset.billedReceiptDetails);
  });
  document.querySelectorAll("[data-fee-receipt-not-received]").forEach((btn) => {
    btn.onclick = () => openFeeReceiptNotReceivedModal(btn.dataset.feeReceiptNotReceived);
  });
  document.querySelectorAll("[data-mark-not-received]").forEach((btn) => {
    btn.onclick = async () => {
      if (!["Admin", "Manager"].includes(normalizeRole(state.currentRole))) {
        return toast("Only Admin or Manager can reverse an unlinked fee receipt.");
      }
      const file = state.files.find((item) => item.id === btn.dataset.markNotReceived);
      if (!file) return toast("File record not found.");
      if (linkedFeeReceiptCollection(file)) {
        return toast("This fee receipt has a linked collection. Delete the linked transaction to return the file to Fee Pending.");
      }
      btn.disabled = true;
      try {
        if (isSupabaseMode()) {
          await reverseUnlinkedFeeReceiptToApi(file.id);
        } else {
          const index = state.files.findIndex((item) => item.id === file.id);
          state.files[index] = {
            ...file,
            billed: true,
            billingType: "Billable",
            feeReceived: false,
            feeReceivedDate: "",
            feeReceivedAt: "",
            fee_received_at: "",
            receivedAt: "",
            received_at: "",
            receivedDate: "",
            received_date: "",
            receivedOn: "",
            received_on: "",
            feeReceivedAmount: 0,
            amountReceived: 0,
            amount_received: 0,
            balanceAmount: Number(file.billedAmount || file.feeAmount || file.amount || 0),
            paymentStatus: "Fee Not Received",
            payment_status: "Fee Not Received",
            paymentMode: "",
            receiptMode: "",
            feeCollectionMode: "",
            feeReceiptRemarks: "",
            receiptRemarks: "",
            feeReceiptId: "",
            fee_receipt_id: "",
            feeTransactionId: "",
            fee_transaction_id: "",
            transactionId: "",
            transaction_id: "",
            feeReceivedBy: "",
            stages: { ...normalizeStages(file), Billed: true },
            updatedAt: Date.now(),
            lastUpdatedDate: todayDate(),
          };
          saveState();
        }
        toast("Fee marked as Not Received and returned to Fee Pending.");
        renderAll();
      } catch (error) {
        toast(error.message || "Unable to reverse this fee receipt.");
        btn.disabled = false;
      }
    };
  });
  document.querySelectorAll("[data-go-transactions]").forEach((btn) => {
    btn.onclick = () => {
      if (!canUseExpenseModule()) return toast("Only Admin or Manager can access Transactions.");
      openFilesFromDashboard("collections");
    };
  });
  document.querySelectorAll("[data-go-fee-transaction]").forEach((btn) => {
    btn.onclick = () => {
      if (!["Admin", "Manager"].includes(normalizeRole(state.currentRole))) {
        return toast("Only Admin or Manager can view linked fee transactions.");
      }
      const transaction = activeCashCollections().find((item) => item.id === btn.dataset.goFeeTransaction);
      if (!transaction) return toast("The linked collection transaction was not found.");
      viewTransactionDetail("Collection", transaction);
    };
  });
  document.querySelectorAll("[data-delete]").forEach((btn) => {
    btn.onclick = () => {
      const file = state.files.find((f) => f.id === btn.dataset.delete);
      if (!rolePerm().delete) return toast("This role cannot delete records.");
      if (!file) return toast("File record not found.");
      if (confirm(`Delete file record for ${file.name}? This cannot be undone.`)) {
        state.deletedFileIds = [...new Set([...(state.deletedFileIds || []), file.id])];
        state.files = state.files.filter((f) => f.id !== file.id);
        saveState({ skipMerge: true });
        if (isSupabaseMode()) {
          syncFileDeleteToApi(file.id)
            .then(() => {
              toast("File record deleted and synced");
              renderAll();
            })
            .catch(() => toast("File deleted locally, but central sync failed. Please retry."));
          return;
        }
        toast("File record deleted permanently");
        renderAll();
      }
    };
  });
}

function checkCompletedFile(fileId) {
  if (!canManageChecking()) return toast("Only authorised checkers can check completed files.");
  const index = state.files.findIndex((file) => file.id === fileId);
  if (index < 0) return toast("File record not found.");
  const file = { ...state.files[index] };
  if (!isNotCheckedFile(file)) return toast("This file is not pending checking.");
  if (!canCheckFile(file)) {
    addAuditLog("Attempt made to check own work", {
      fileId,
      fileName: file.name,
      attemptedBy: state.currentUser,
      workDoneBy: file.completedBy || file.assignedStaff || "",
    });
    saveState();
    return toast("You cannot check a file completed by yourself. This file must be checked by another authorised user.");
  }
  openCheckingModal(file);
}

function openCheckingModal(file) {
  const checkedBy = state.currentUser || loggedInUser()?.name || "";
  const drawer = document.querySelector("#fileDrawer");
  drawer.innerHTML = `
    <div class="drawer-head">
      <div><h3>Check File</h3><p class="small-muted">Confirm the checking details for ${escapeHtml(file.name || "this file")}.</p></div>
      <button class="icon-button" id="closeCheckingModal" title="Close">X</button>
    </div>
    <form id="checkingForm" class="drawer-body">
      <div class="checking-summary">
        <strong>${escapeHtml(file.name || "")}</strong>
        <span>${escapeHtml(file.serviceType || "")}${file.fy ? ` · FY ${escapeHtml(file.fy)}` : ""}</span>
      </div>
      <div class="field">
        <label>Checking Date</label>
        <input type="date" name="checkingDate" value="${todayDate()}" required>
      </div>
      <div class="field">
        <label>Checking Remarks</label>
        <textarea name="checkingRemarks" rows="5" placeholder="Enter verification notes or observations" required>${escapeHtml(file.checkingRemarks || "")}</textarea>
      </div>
      ${checkingDetailField("Checked By", checkedBy || "-")}
    </form>
    <div class="drawer-actions">
      <button class="secondary-button" id="cancelChecking">Cancel</button>
      <button class="primary-button" id="confirmChecking">Confirm Check</button>
    </div>`;
  drawer.classList.add("open");
  document.querySelector("#backdrop").classList.add("show");
  document.querySelector("#closeCheckingModal").onclick = closeOverlays;
  document.querySelector("#cancelChecking").onclick = closeOverlays;
  document.querySelector("#confirmChecking").onclick = () => submitCheckingForm(file.id);
}

async function submitCheckingForm(fileId) {
  const form = document.querySelector("#checkingForm");
  const button = document.querySelector("#confirmChecking");
  if (!form || !button) return;
  const data = new FormData(form);
  const checkingDate = String(data.get("checkingDate") || "").trim();
  const checkingRemarks = String(data.get("checkingRemarks") || "").trim();
  if (!checkingDate) return toast("Please select a Checking Date.");
  if (!validCheckingRemark(checkingRemarks)) return toast("Please enter a valid Checking Remark containing at least two characters before marking this file as Checked.");
  const index = state.files.findIndex((file) => file.id === fileId);
  if (index < 0) return toast("File record not found.");
  const file = { ...state.files[index] };
  if (!isNotCheckedFile(file)) return toast("This file is no longer pending checking.");
  button.disabled = true;
  button.textContent = "Checking...";
  if (isSupabaseMode()) {
    try {
      const result = await markFileCheckedInApi(fileId, checkingRemarks, checkingDate);
      if (result?.file) state.files = state.files.map((item) => (item.id === fileId ? { ...item, ...result.file } : item));
      if (result?.fileNotifications) state.fileNotifications = mergeFileNotifications(state.fileNotifications || [], result.fileNotifications).slice(0, 500);
      saveState({ skipMerge: true, skipRemote: true });
      toast("File marked as checked and synced");
      closeOverlays();
      renderAll();
      return;
    } catch (error) {
      console.error("Checking update failed", { fileId, message: error.message });
      button.disabled = false;
      button.textContent = "Confirm Check";
      return toast(`Checking update failed: ${error.message || "Please retry."}`);
    }
  }
  const checkedAt = new Date().toISOString();
  const checkedBy = state.currentUser || loggedInUser()?.name || "";
  const updated = {
    ...file,
    checkedBy,
    checkedDate: checkingDate,
    checkedAt,
    checked_at: checkedAt,
    finalCompletedAt: file.finalCompletedAt || file.final_completed_at || checkedAt,
    final_completed_at: file.final_completed_at || file.finalCompletedAt || checkedAt,
    checkingRemarks,
    lastUpdatedDate: checkingDate,
    updatedAt: Date.now(),
    taskActivityAt: checkedAt,
    task_activity_at: checkedAt,
  };
  state.files[index] = updated;
  queueFileCheckedNotification(updated, file);
  addAuditLog("File marked Checked", {
    fileId,
    fileName: file.name,
    previousCheckingStatus: checkingStatusOf(file).label,
    newCheckingStatus: "Checked",
    checkedBy,
    checkedDate: checkingDate,
    checkedAt,
    checkerUserId: state.session?.userId || loggedInUser()?.id || "",
    checkingRemarks,
  });
  saveState();
  try {
    await syncFileRecordToApi(updated);
  } catch {
    return toast("Checked locally, but central sync failed. Please retry.");
  }
  toast("File marked as checked and synced");
  closeOverlays();
  renderAll();
}

function openStaffFilesFromDashboard(kind) {
  resetFilters();
  if (kind === "active") state.filters.listView = "active";
  if (kind === "all") state.filters.listView = "";
  if (kind === "completed") state.filters.listView = "completed";
  if (kind === "notChecked") state.filters.listView = "notChecked";
  if (kind === "billed") state.filters.listView = "billed";
  if (kind === "unbilled") state.filters.listView = "nonBilled";
  if (kind === "onHold") state.filters.workflow = "On Hold";
  if (kind === "clientPending") state.filters.workflow = "Client Pending";
  if (kind === "overdue") state.filters.overdue = "Yes";
  if (kind === "approval") state.filters.pendingApproval = "Yes";
  if (kind === "correction") state.filters.dashboardKind = "correctionRequired";
  if (kind === "reallotted") state.filters.dashboardKind = "reAllotted";
  state.filters.fromDashboard = "Yes";
  saveState();
  activePage = "files";
  renderAll();
}

async function returnFileForCorrection(fileId) {
  if (!canManageChecking()) return toast("Only authorised checkers can return files for correction.");
  const index = state.files.findIndex((file) => file.id === fileId);
  if (index < 0) return toast("File record not found.");
  const file = { ...state.files[index] };
  if (!isCheckedCompleted(file)) return toast("Only completed files can be returned for correction.");
  const correctionRemarks = prompt("Correction remarks")?.trim();
  if (!correctionRemarks) return toast("Correction remarks are required.");
  if (isSupabaseMode()) {
    try {
      const result = await apiJson(`/api/files/${encodeURIComponent(fileId)}/return-correction`, {
        method: "POST",
        body: JSON.stringify({ correctionReason: correctionRemarks }),
      });
      if (result.files) state.files = result.files;
      if (result.correctionHistory) state.correctionHistory = result.correctionHistory;
      if (result.fileNotifications) state.fileNotifications = mergeFileNotifications(state.fileNotifications || [], result.fileNotifications).slice(0, 500);
      saveState({ skipMerge: true, skipRemote: true });
      toast("File returned for correction and synced");
      renderAll();
      return;
    } catch (error) {
      console.error("Failed correction update", { fileId, message: error.message });
      return toast(`Correction sync failed: ${error.message || "Please retry."}`);
    }
  }
  const returnedDate = todayDate();
  const returnedTo = findUserByStaffIdentity(file.assignedStaffId)
    || findUserByStaffIdentity(file.assignedStaffEmail)
    || findUserByStaffIdentity(file.assignedStaff)
    || {};
  const correction = {
    id: crypto.randomUUID(),
    fileId,
    file_id: fileId,
    correctionReason: correctionRemarks,
    correction_reason: correctionRemarks,
    returnedBy: state.currentUser || "",
    returnedById: state.session?.userId || "",
    returnedByEmail: state.session?.userEmail || "",
    returnedTo: returnedTo.name || file.assignedStaff || "",
    returnedToId: returnedTo.id || file.assignedStaffId || "",
    returnedToEmail: returnedTo.email || file.assignedStaffEmail || "",
    returnedAt: new Date().toISOString(),
    returnedDate,
    status: "Returned for Correction",
    response: "",
  };
  const stagesObj = { ...normalizeStages(file), ...(file.stages || {}) };
  stagesObj["Correction Required"] = true;
  stagesObj["Corrected & Completed"] = false;
  stagesObj.Completed = false;
  stagesObj.Billed = Boolean(file.billed);
  const updated = {
    ...file,
    stages: stagesObj,
    filed: false,
    checkedBy: "",
    checkedDate: "",
    checkingRemarks: "",
    correctionRemarks,
    returnedBy: correction.returnedBy,
    returnedById: correction.returnedById,
    returnedByEmail: correction.returnedByEmail,
    returnedTo: correction.returnedTo,
    returnedToId: correction.returnedToId,
    returnedToEmail: correction.returnedToEmail,
    returnedDate,
    correctionStatus: correction.status,
    correctionHistory: [...(file.correctionHistory || []), correction],
    lastUpdatedDate: returnedDate,
    updatedAt: Date.now(),
    taskActivityAt: correction.returnedAt,
    task_activity_at: correction.returnedAt,
  };
  state.files[index] = updated;
  state.correctionHistory = [...(state.correctionHistory || []), correction];
  queueFileChangeNotification(updated, `Returned for correction: ${correctionRemarks}`, "Returned for Correction");
  addAuditLog("File returned for correction", {
    fileId,
    fileName: file.name,
    previousStatus: statusOf(file).label,
    newStatus: "Correction Required",
    correctionRemarks,
    returnedBy: updated.returnedBy,
    returnedDate,
  });
  saveState();
  try {
    await syncFileRecordToApi(updated);
  } catch {
    return toast("Correction saved locally, but central sync failed. Please retry.");
  }
  toast("File returned for correction and synced");
  renderAll();
}

function renderCorrectionRequiredTable(files) {
  const rows = sortFilesByCorrectionNewestFirst(files);
  const compactStaffCorrectionView = !["Admin", "Manager"].includes(state.currentRole);
  if (!rows.length) return empty("No correction-required files found.");
  return `
    <div class="table-wrap file-table-wrap">
      <table class="file-table file-table-compact correction-required-table">
        <thead><tr>
          <th>SN</th><th>Client Name</th><th>CR No.</th><th>Service Type</th>${compactStaffCorrectionView ? "" : "<th>File Received Date</th><th>Assigned Staff</th>"}<th>Completed Date</th><th>Returned On</th><th>Required By</th><th>Correction Reason</th><th>Status</th><th>Priority</th>${compactStaffCorrectionView ? "" : "<th>Expected Date</th><th>Aging</th><th>Last Updated</th>"}<th>Actions</th>
        </tr></thead>
        <tbody>
          ${rows.map((file, index) => {
            const correction = latestCorrectionForFile(file) || {};
            const returnedOn = correction.returnedAt || correction.returned_at || file.returnedAt || file.returned_at || file.returnedDate || "";
            const reason = correction.correctionReason || correction.correction_reason || file.correctionRemarks || "";
            const requiredBy = correction.returnedBy || correction.returned_by_name || file.returnedBy || "-";
            const expected = correction.expectedCorrectionDate || correction.expected_correction_date || file.expectedCorrectionDate || "";
            const status = file.correctionStatus || correction.status || "Correction Required";
            return `<tr class="file-row file-row-overdue">
              <td>${index + 1}</td>
              <td class="client-details-cell">${clientDetailsCell(file)}</td>
              <td>${escapeHtml(file.crNo || file.cr_no || file.pan || "-")}</td>
              <td>${escapeHtml(file.serviceType || "")}</td>
              ${compactStaffCorrectionView ? "" : `<td>${fmt(file.fileReceivedDate)}</td><td>${escapeHtml(file.assignedStaff || file.returnedTo || "Not Assigned")}</td>`}
              <td>${fmt(workCompletedDate(file))}</td>
              <td>${escapeHtml(fmt(returnedOn) || "-")}</td>
              <td>${escapeHtml(requiredBy)}</td>
              <td class="correction-reason-cell">${escapeHtml(reason || "-")}</td>
              <td><span class="badge overdue">${escapeHtml(status)}</span></td>
              <td><span class="badge priority-${String(file.priority || "Medium").toLowerCase()}">${escapeHtml(file.priority || "Medium")}</span></td>
              ${compactStaffCorrectionView ? "" : `<td>${fmt(expected)}</td><td>${returnedOn ? agingText(returnedOn) : "-"}</td><td>${fmt(file.lastUpdatedDate || file.updated_at || file.updatedAt)}</td>`}
              <td><div class="action-row"><button class="mini-button" data-edit="${file.id}">View File</button></div></td>
            </tr>`;
          }).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function openMarkReceivedModal(fileId) {
  const file = state.files.find((item) => item.id === fileId);
  if (!file) return toast("File record not found.");
  if (!rolePerm().assign) return toast("This role cannot update billing.");
  closeMarkReceivedModal();
  const receipt = feeReceiptDetails(file);
  const receiptSummary = feeReceiptSummaryForFile(file);
  receipt.receivedAmount = receiptSummary.outstandingAmount > 0 ? receiptSummary.outstandingAmount : "";
  const modal = document.createElement("div");
  modal.id = "markReceivedModal";
  modal.className = "simple-modal open";
  modal.dataset.existingReceived = String(receiptSummary.totalReceived || 0);
  modal.dataset.existingDiscount = String(receiptSummary.totalDiscount || 0);
  modal.innerHTML = `
    <div class="simple-modal-card receipt-modal-card">
      <div class="drawer-head">
        <div>
          <h3>Mark Fee Received</h3>
          <p class="small-muted">${escapeHtml(file.name || "File")} | ${escapeHtml(file.serviceType || "")}</p>
        </div>
        <button class="icon-button" id="closeReceivedModal">X</button>
      </div>
      <div class="drawer-body">
        <div class="receipt-form-grid">
          <div class="receipt-form-row receipt-billing-row">
            ${feeReceiptField("receiptBillDate", "Bill Date", receipt.billDate, "date")}
            ${feeReceiptField("receiptBillNo", "Invoice No.", receipt.billNo, "text", "pattern='[A-Za-z0-9/-]*'")}
            ${feeReceiptField("receiptBilledAmount", "Amount", receipt.billedAmount, "number", "min='0.01' step='0.01'")}
          </div>
          <div class="receipt-form-row receipt-payment-row">
            ${feeReceiptField("receiptReceivedDate", "Received On", receipt.receivedDate, "date")}
            ${feeReceiptField("receiptReceivedAmount", "Received Amount", receipt.receivedAmount, "number", `min='0.01' max='${receiptSummary.outstandingAmount}' step='0.01'`)}
            ${feeReceiptField("receiptDiscountAmount", "Discount", receipt.discountAmount, "number", "min='0' step='0.01'")}
            ${feeReceiptSelect("receiptPaymentMode", "Mode", paymentModes(), receipt.paymentMode)}
          </div>
          ${feeReceiptAccountSelect("receiptAccount", "Account", receipt.accountKey)}
          ${feeReceiptTextarea("receiptRemarks", "Remarks", receipt.remarks)}
        </div>
        ${feeReceiptModalStatus(file)}
        ${feeReceiptPushControl(file)}
      </div>
      <div class="drawer-actions">
        <button class="secondary-button" id="cancelReceivedModal">Cancel</button>
        <button class="primary-button" id="saveReceivedModal">Save Receipt</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  document.querySelector("#backdrop")?.classList.add("show");
  document.querySelector("#closeReceivedModal").onclick = closeMarkReceivedModal;
  document.querySelector("#cancelReceivedModal").onclick = closeMarkReceivedModal;
  document.querySelector("#saveReceivedModal").onclick = () => saveReceivedFromModal(fileId);
  document.querySelectorAll("[name='receiptBilledAmount'], [name='receiptReceivedAmount'], [name='receiptDiscountAmount']").forEach((input) => {
    input.addEventListener("input", updateFeeReceiptBalancePreview);
  });
  bindPaymentAccountControls("[name='receiptPaymentMode']", "[name='receiptAccount']");
  updateFeeReceiptBalancePreview();
}

function closeMarkReceivedModal() {
  document.querySelector("#markReceivedModal")?.remove();
  if (!document.querySelector(".drawer.open") && !document.querySelector(".notification-panel.open")) {
    document.querySelector("#backdrop")?.classList.remove("show");
  }
}

async function saveReceivedFromModal(fileId) {
  const file = state.files.find((item) => item.id === fileId) || {};
  const currentSummary = feeReceiptSummaryForFile(file);
  const receipt = feeReceiptFromModal(file);
  const validationMessage = validateFeeReceipt(receipt, currentSummary.outstandingAmount);
  if (validationMessage) return toast(validationMessage);
  const button = document.querySelector("#saveReceivedModal");
  if (button) button.disabled = true;
  const user = loggedInUser() || {};
  const receivedAt = new Date().toISOString();
  const totalDiscount = Number(currentSummary.totalDiscount || 0) + Number(receipt.discountAmount || 0);
  const balanceAmount = Math.max(Number(receipt.billedAmount || 0) - currentSummary.totalReceived - Number(receipt.receivedAmount || 0) - totalDiscount, 0);
  let linkedTransaction = null;
  if (isSupabaseMode()) {
    try {
      const collection = receipt.pushToTransactions ? feeReceiptCollectionPayload(file, receipt) : null;
      const result = await saveLinkedFeeReceiptToApi(fileId, { ...receipt, receivedAt }, collection);
      if (button) button.disabled = false;
      closeMarkReceivedModal();
      toast(receipt.pushToTransactions ? "Fee receipt saved and collection linked successfully." : "Fee receipt saved successfully.");
      renderAll();
      return result;
    } catch (error) {
      console.error("Fee receipt save failed", error);
      if (button) button.disabled = false;
      return toast(`Fee receipt save failed: ${error.message || "Please retry."}`);
    }
  }
  if (receipt.pushToTransactions) {
    try {
      linkedTransaction = await saveFeeReceiptCollection(file, receipt);
      receipt.transactionId = linkedTransaction.id;
    } catch (error) {
      console.error("Fee receipt transaction push failed", error);
      if (button) button.disabled = false;
      return toast(`Receipt not pushed: ${error.message || "Please retry."}`);
    }
  }
  state.feeReceipts = [{
    ...receipt,
    id: receipt.feeReceiptId,
    fileId,
    file_id: fileId,
    receiptDate: receipt.receivedDate,
    receipt_date: receipt.receivedDate,
    amount: receipt.receivedAmount,
    discountAmount: receipt.discountAmount,
    discount_amount: receipt.discountAmount,
    discount: receipt.discountAmount,
    receivedAt,
    received_at: receivedAt,
    receivedBy: user.name || state.currentUser || "",
    received_by: user.name || state.currentUser || "",
    status: "active",
    transactionId: linkedTransaction?.id || "",
    transaction_id: linkedTransaction?.id || "",
  }, ...(state.feeReceipts || [])];
  const ok = await updateFileBilling(fileId, {
    billed: true,
    billingType: "Billable",
    billedDate: receipt.billDate,
    billDate: receipt.billDate,
    bill_date: receipt.billDate,
    billNo: receipt.billNo,
    bill_number: receipt.billNo,
    invoiceNumber: receipt.billNo,
    invoiceNo: receipt.billNo,
    billedAmount: receipt.billedAmount,
    billed_amount: receipt.billedAmount,
    billAmount: receipt.billedAmount,
    feeAmount: receipt.billedAmount,
    amount: receipt.billedAmount,
    feeReceived: balanceAmount <= 0,
    feeReceivedDate: receipt.receivedDate,
    feeReceivedAmount: currentSummary.totalReceived + receipt.receivedAmount,
    amount_received: currentSummary.totalReceived + receipt.receivedAmount,
    amountReceived: currentSummary.totalReceived + receipt.receivedAmount,
    discountAmount: totalDiscount,
    discount_amount: totalDiscount,
    balanceAmount,
    balance_amount: balanceAmount,
    received_date: receipt.receivedDate,
    receivedDate: receipt.receivedDate,
    received_on: receipt.receivedDate,
    receivedOn: receipt.receivedDate,
    paymentMode: receipt.paymentMode,
    receiptMode: receipt.paymentMode,
    feeCollectionMode: receipt.paymentMode,
    feeReceiptRemarks: receipt.remarks,
    receiptRemarks: receipt.remarks,
    receipt_remarks: receipt.remarks,
    feeReceiptId: receipt.feeReceiptId,
    fee_receipt_id: receipt.feeReceiptId,
    received_by_user_id: user.id || state.session?.userId || "",
    received_by_user_name: user.name || state.currentUser || "",
    receivedByUserId: user.id || state.session?.userId || "",
    receivedByUserName: user.name || state.currentUser || "",
    received_at: receivedAt,
    receivedAt,
    fee_received_at: receivedAt,
    feeReceivedAt: receivedAt,
    feeReceivedBy: user.name || state.currentUser || "",
    payment_status: balanceAmount > 0 ? "Partly Received" : "Fee Received",
    paymentStatus: balanceAmount > 0 ? "Partly Received" : "Fee Received",
    ...updateFeeReceiptTransactionStatus(file, linkedTransaction),
  }, "Fee receipt saved", balanceAmount > 0 ? "feePending" : "feeReceived");
  if (button) button.disabled = false;
  if (ok) closeMarkReceivedModal();
}

async function updateFileBilling(fileId, updates, message, nextListView = "") {
  if (!rolePerm().assign) return toast("This role cannot update billing.");
  const index = state.files.findIndex((file) => file.id === fileId);
  if (index < 0) return toast("File record not found.");
  const file = { ...state.files[index] };
  const stagesObj = { ...normalizeStages(file), ...(file.stages || {}) };
  if (Object.prototype.hasOwnProperty.call(updates, "billed")) stagesObj.Billed = Boolean(updates.billed);
  const updated = {
    ...file,
    ...updates,
    stages: stagesObj,
    lastUpdatedDate: todayDate(),
    updatedAt: Date.now(),
  };
  applyFeeReceivedTimestamp(updated, file);
  state.files[index] = updated;
  if (["billed", "feePending"].includes(state.filters.listView)) {
    addAuditLog("Billed file updated", {
      fileId: file.id,
      clientName: file.name || "",
      serviceType: file.serviceType || "",
      actionPerformed: message,
      previousValue: { billingType: file.billingType, billed: file.billed, feeReceived: file.feeReceived, billAmount: dashboardFileAmount(file, "billed") },
      newValue: { billingType: updated.billingType, billed: updated.billed, feeReceived: updated.feeReceived, billAmount: dashboardFileAmount(updated, "billed") },
    });
  }
  queueFileChangeNotification(updated, billingChangeText(file, updated), updates.billed ? "Billed" : updates.feeReceived ? "Fee Received" : "Billing Update");
  saveState();
  try {
    await syncFileRecordToApi(updated);
  } catch {
    toast("Billing saved locally, but central sync failed. Please retry.");
    return false;
  }
  toast(/successfully/i.test(message) ? message : `${message} and synced`);
  renderAll();
  return true;
}

