function dailyReportPdfDefinition(section = {}) {
  const definitions = {
    "Balance Summary": {
      columns: [
        { header: "Account", dataKey: "account" },
        { header: "Closing Balance", dataKey: "amount" },
      ],
      rows: section.rows.map((row) => ({ account: row.Account, amount: billedPdfMoney(dailyReportPdfNumber(row["Closing Balance"])) })),
      widths: { account: { cellWidth: 335 }, amount: { cellWidth: 200, halign: "right" } },
      amountKey: "amount",
    },
    "Completed Files": {
      columns: [
        { header: "SN", dataKey: "sn" }, { header: "Client Name", dataKey: "client" },
        { header: "Service Type", dataKey: "service" }, { header: "C/o", dataKey: "careOf" },
        { header: "Done By", dataKey: "doneBy" }, { header: "Checked By", dataKey: "checkedBy" },
        { header: "Billed Status", dataKey: "billedStatus" },
      ],
      rows: section.rows.map((row) => ({ sn: row.SN, client: row.Name || "-", service: row["Type of Service"] || "-", careOf: row["C/o"] || "Direct", doneBy: row["Work Done By"] || "Not Recorded", checkedBy: row["Checked By"] || "Not Recorded", billedStatus: row["Billed Status"] || "Not Billed" })),
      widths: { sn: { cellWidth: 22, halign: "center" }, client: { cellWidth: 120 }, service: { cellWidth: 120 }, careOf: { cellWidth: 50 }, doneBy: { cellWidth: 75 }, checkedBy: { cellWidth: 75 }, billedStatus: { cellWidth: 73, halign: "center" } },
    },
    "New Work Came": {
      columns: [
        { header: "SN", dataKey: "sn" }, { header: "Client Name", dataKey: "client" },
        { header: "Service Type", dataKey: "service" }, { header: "C/o", dataKey: "careOf" },
        { header: "Assigned To", dataKey: "staff" }, { header: "Status", dataKey: "status" },
        { header: "Completion On", dataKey: "completionOn" },
      ],
      rows: section.rows.map((row) => ({ sn: row.SN, client: row.Name || "-", service: row["Type of Service"] || "-", careOf: row["C/o"] || "Direct", staff: row["Assigned To"] || "Not Assigned", status: row.Status || "-", completionOn: row["Completion On"] || "-" })),
      widths: { sn: { cellWidth: 22, halign: "center" }, client: { cellWidth: 120 }, service: { cellWidth: 120 }, careOf: { cellWidth: 50 }, staff: { cellWidth: 80 }, status: { cellWidth: 60, halign: "center" }, completionOn: { cellWidth: 83, halign: "center" } },
    },
    "Visitors List": {
      columns: [
        { header: "SN", dataKey: "sn" }, { header: "Visitor Name", dataKey: "visitor" },
        { header: "Mobile No", dataKey: "mobile" }, { header: "Company", dataKey: "company" },
        { header: "Purpose", dataKey: "purpose" }, { header: "Time", dataKey: "time" }, { header: "Met", dataKey: "met" },
      ],
      rows: section.rows.map((row) => ({ sn: row.SN, visitor: row["Visitor Name"] || "-", mobile: row["Mobile No"] || "Not Recorded", company: row.Company || "-", purpose: row.Purpose || "-", time: row.Time || "-", met: row.Met || "-" })),
      widths: { sn: { cellWidth: 22, halign: "center" }, visitor: { cellWidth: 90 }, mobile: { cellWidth: 70 }, company: { cellWidth: 85 }, purpose: { cellWidth: 140 }, time: { cellWidth: 50, halign: "center" }, met: { cellWidth: 78 } },
    },
    "Expense Report": {
      columns: [
        { header: "SN", dataKey: "sn" }, { header: "Expense Item", dataKey: "item" },
        { header: "Paid To", dataKey: "paidTo" }, { header: "Method", dataKey: "method" },
        { header: "Account", dataKey: "account" }, { header: "Voucher No.", dataKey: "voucher" },
        { header: "Amount", dataKey: "amount" },
      ],
      rows: section.rows.map((row) => ({ sn: row.SN, item: row["Expense Item"] || "-", paidTo: row["Paid To"] || "-", method: row["Payment Method"] || "-", account: row.Account || "Not Recorded", voucher: row["Voucher No."] || "-", amount: billedPdfMoney(dailyReportPdfNumber(row.Amount)) })),
      widths: { sn: { cellWidth: 22, halign: "center" }, item: { cellWidth: 130 }, paidTo: { cellWidth: 85 }, method: { cellWidth: 60 }, account: { cellWidth: 78 }, voucher: { cellWidth: 70 }, amount: { cellWidth: 90, halign: "right" } },
      amountKey: "amount",
    },
    Collections: {
      columns: [
        { header: "SN", dataKey: "sn" }, { header: "Received From", dataKey: "from" },
        { header: "Service Type", dataKey: "service" }, { header: "Mode", dataKey: "mode" },
        { header: "Account", dataKey: "account" }, { header: "Ref No", dataKey: "reference" },
        { header: "Amount", dataKey: "amount" },
      ],
      rows: section.rows.map((row) => ({ sn: row.SN, from: row["Received From"] || "-", service: row["Service Type"] || "-", mode: row.Mode || "-", account: row.Account || "Not Recorded", reference: row["Ref No"] || "-", amount: billedPdfMoney(dailyReportPdfNumber(row.Amount)) })),
      widths: { sn: { cellWidth: 22, halign: "center" }, from: { cellWidth: 110 }, service: { cellWidth: 110 }, mode: { cellWidth: 60 }, account: { cellWidth: 75 }, reference: { cellWidth: 68 }, amount: { cellWidth: 90, halign: "right" } },
      amountKey: "amount",
    },
  };
  return definitions[section.title] || {
    columns: [{ header: "Details", dataKey: "details" }],
    rows: section.rows.map((row) => ({ details: Object.values(row).join(" | ") })),
    widths: { details: { cellWidth: 535 } },
  };
}

function dailyReportPdfTotalLabel(section = {}) {
  const rows = section.rows || [];
  if (section.title === "Balance Summary") {
    const total = rows.find((row) => row.Account === "Total Balance")?.["Closing Balance"] || 0;
    return `Total Balance: ${billedPdfMoney(dailyReportPdfNumber(total))}`;
  }
  if (section.title === "Completed Files") return `Total Completed Files: ${rows.length}`;
  if (section.title === "New Work Came") return `Total New Work Received: ${rows.length}`;
  if (section.title === "Visitors List") return `Total Visitors: ${rows.length}`;
  if (section.title === "Expense Report") return `Total Expenses: ${billedPdfMoney(rows.reduce((sum, row) => sum + dailyReportPdfNumber(row.Amount), 0))}`;
  if (section.title === "Collections") return `Total Collections: ${billedPdfMoney(rows.reduce((sum, row) => sum + dailyReportPdfNumber(row.Amount), 0))}`;
  return section.total || `Total Records: ${rows.length}`;
}

function drawDailyReportPdfSection(doc, context, section, startY) {
  let y = startY;
  if (y + 78 > context.pageHeight - 34) {
    doc.addPage();
    drawDailyReportPdfCompactHeader(doc, context);
    y = 54;
  }
  doc.setFillColor(...BILLED_PDF_COLORS.lightBlue);
  doc.setDrawColor(...BILLED_PDF_COLORS.border);
  doc.roundedRect(30, y, context.pageWidth - 60, 24, 3, 3, "FD");
  doc.setTextColor(...BILLED_PDF_COLORS.navy);
  doc.setFont("DejaVuSans", "bold");
  doc.setFontSize(9.3);
  const displayTitle = section.title === "New Work Came" ? "New Work Received" : String(section.title || "");
  doc.text(displayTitle, 38, y + 16);
  const rows = section.rows || [];
  if (!rows.length) {
    doc.setFillColor(248, 250, 252);
    doc.setDrawColor(...BILLED_PDF_COLORS.border);
    doc.roundedRect(30, y + 30, context.pageWidth - 60, 34, 3, 3, "FD");
    doc.setTextColor(...BILLED_PDF_COLORS.muted);
    doc.setFont("DejaVuSans", "normal");
    doc.setFontSize(7.3);
    doc.text(section.empty || "No records found for the selected date.", 40, y + 51);
    doc.setTextColor(...BILLED_PDF_COLORS.navy);
    doc.setFont("DejaVuSans", "bold");
    doc.text(dailyReportPdfTotalLabel(section), context.pageWidth - 38, y + 51, { align: "right" });
    return y + 78;
  }
  const definition = dailyReportPdfDefinition(section);
  doc.autoTable({
    startY: y + 30,
    columns: definition.columns,
    body: definition.rows,
    theme: "grid",
    showHead: "everyPage",
    pageBreak: "auto",
    rowPageBreak: "avoid",
    margin: { left: 30, right: 30, top: 50, bottom: 58 },
    tableWidth: context.pageWidth - 60,
    styles: { font: "DejaVuSans", fontSize: 7, cellPadding: 3.2, overflow: "linebreak", valign: "middle", textColor: BILLED_PDF_COLORS.text, lineColor: BILLED_PDF_COLORS.border, lineWidth: 0.3, minCellHeight: 22 },
    headStyles: { font: "DejaVuSans", fontStyle: "bold", fontSize: 7.2, fillColor: BILLED_PDF_COLORS.navy, textColor: [255, 255, 255], valign: "middle", lineColor: BILLED_PDF_COLORS.border, lineWidth: 0.35, minCellHeight: 23 },
    alternateRowStyles: { fillColor: BILLED_PDF_COLORS.alternate },
    columnStyles: definition.widths,
    willDrawPage: () => {
      if (doc.internal.getCurrentPageInfo().pageNumber > 1) drawDailyReportPdfCompactHeader(doc, context);
    },
    didParseCell: (data) => {
      if (data.section === "body" && definition.amountKey && data.column.dataKey === definition.amountKey) {
        data.cell.styles.fontStyle = "bold";
        data.cell.styles.textColor = section.title === "Expense Report" ? BILLED_PDF_COLORS.red : BILLED_PDF_COLORS.green;
      }
      if (data.section === "body" && section.title === "Balance Summary" && data.row.index === definition.rows.length - 1) {
        data.cell.styles.fontStyle = "bold";
        data.cell.styles.fillColor = BILLED_PDF_COLORS.lightBlue;
      }
    },
  });
  y = doc.lastAutoTable.finalY + 5;
  doc.setFillColor(248, 250, 252);
  doc.setDrawColor(...BILLED_PDF_COLORS.border);
  doc.roundedRect(30, y, context.pageWidth - 60, 22, 3, 3, "FD");
  doc.setTextColor(...BILLED_PDF_COLORS.navy);
  doc.setFont("DejaVuSans", "bold");
  doc.setFontSize(7.2);
  doc.text(dailyReportPdfTotalLabel(section), context.pageWidth - 38, y + 15, { align: "right" });
  return y + 34;
}

function dailyAutoFitPdfColumnStyles(headers, tableWidth) {
  if (!headers.length) return {};
  const styles = {};
  const snIndex = headers.indexOf("SN");
  const fixedWidth = snIndex >= 0 ? 28 : 0;
  const flexibleHeaders = headers.filter((_, index) => index !== snIndex);
  const flexibleWidth = Math.max(46, (tableWidth - fixedWidth) / Math.max(1, flexibleHeaders.length));
  headers.forEach((header, index) => {
    if (header === "SN") {
      styles[index] = { cellWidth: fixedWidth, halign: "center" };
    } else if (/amount|total|fee/i.test(header)) {
      styles[index] = { cellWidth: flexibleWidth, halign: "right" };
    } else {
      styles[index] = { cellWidth: flexibleWidth };
    }
  });
  return styles;
}

