async function downloadDailyReportWorkbook(date, newWorkRows, completedRows, visitorRows, collectionRows, expenseRows, balanceSummary = emptyDailyReportBalanceSummary(date)) {
  const title = `Daily Report M&A - ${displayDate(date)}`;
  const balanceRows = [
    { Account: title, "Closing Balance": "" },
    { Account: `Balance Summary as at ${displayDate(date)}`, "Closing Balance": "" },
    ...dailyReportBalanceRows(balanceSummary, true),
  ];
  await downloadXlsxSheets(`daily-report-${date}`, [
    { name: "Balance Summary", rows: balanceRows, prepare: (worksheet) => {
      worksheet["!cols"] = [{ wch: 30 }, { wch: 20 }];
      for (let row = 4; row <= 7; row += 1) {
        const cell = worksheet[`B${row}`];
        if (cell) cell.z = '₹#,##0.00';
      }
      ["A7", "B7"].forEach((address) => { if (worksheet[address]) worksheet[address].s = { font: { bold: true } }; });
    } },
    { name: "New Work Came", rows: [{ SN: "", Name: title, "Type of Service": "", "C/o": "", "Assigned To": "" }, ...newWorkRows, { SN: "", Name: `Total New Work Received: ${newWorkRows.length}`, "Type of Service": "", "C/o": "", "Assigned To": "" }] },
    { name: "Completed Files", rows: [{ SN: "", Name: title, "Type of Service": "", "C/o": "", "Work Done By": "", "Checked By": "" }, ...completedRows, { SN: "", Name: `Total Completed Files: ${completedRows.length}`, "Type of Service": "", "C/o": "", "Work Done By": "", "Checked By": "" }] },
    { name: "Visitors List", rows: [{ SN: "", "Visitor Name": title, "Mobile No": "", Company: "", Purpose: "", Time: "", Met: "" }, ...visitorRows, { SN: "", "Visitor Name": `Total Visitors: ${visitorRows.length}`, "Mobile No": "", Company: "", Purpose: "", Time: "", Met: "" }] },
    { name: "Collections", rows: [{ SN: "", "Received From": title, "Service Type": "", Mode: "", Account: "", "Ref No": "", Amount: "" }, ...collectionRows, { SN: "", "Received From": "Total Collections", "Service Type": "", Mode: "", Account: "", "Ref No": "", Amount: money(collectionRows.reduce((sum, row) => sum + Number(String(row.Amount).replace(/,/g, "") || 0), 0)) }] },
    { name: "Expense Report", rows: [{ SN: "", Date: title, "Expense Item": "", "Paid To": "", "Payment Method": "", Account: "", "Voucher No.": "", Amount: "", "Paid By": "" }, ...expenseRows, { SN: "", Date: "", "Expense Item": "Total Expenses", "Paid To": "", "Payment Method": "", Account: "", "Voucher No.": "", Amount: money(expenseRows.reduce((sum, row) => sum + Number(String(row.Amount).replace(/,/g, "") || 0), 0)), "Paid By": "" }] },
  ]);
}

function printStructuredReport({ title, subtitle = "", sections = [], format = "Print", showPrintAction = true }) {
  const firmName = state.company?.name || "Muhammad & Associates";
  const html = `
    <html>
      <head>
        <title>${escapeHtml(title)}</title>
        <style>
          @page { size: A4 landscape; margin: 10mm; }
          body { font-family: Arial, sans-serif; color: #111827; margin: 0; }
          .report-page { padding: 8px; }
          .firm { color: #1d4ed8; font-size: 11px; font-weight: 800; text-transform: uppercase; margin-bottom: 2px; }
          h1 { margin: 0 0 8px; font-size: 15px; color: #0f172a; }
          .subtitle { margin: -3px 0 8px; color: #334155; font-size: 10px; font-weight: 700; }
          h2 { margin: 10px 0 5px; font-size: 12px; color: #123f6d; }
          table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 10px; page-break-inside: auto; }
          thead { display: table-header-group; }
          th { background: #dceeff; color: #0f3f6f; border: 1px solid #9bc7f5; padding: 4px 5px; text-align: left; }
          td { border: 1px solid #d1d5db; padding: 4px 5px; vertical-align: top; word-wrap: break-word; }
          th:first-child, td:first-child { width: 34px; max-width: 34px; text-align: center; }
          tr { page-break-inside: avoid; }
          tr:nth-child(even) td { background: #f8fafc; }
          .total { margin: 5px 0 0; font-weight: 800; color: #0f172a; font-size: 10px; }
          .empty { padding: 7px; border: 1px dashed #cbd5e1; background: #f8fafc; color: #64748b; font-size: 10px; }
          .screen-actions { position: sticky; top: 0; padding: 8px 0; background: #fff; border-bottom: 1px solid #e5e7eb; margin-bottom: 8px; }
          button { border: 0; border-radius: 8px; padding: 7px 10px; background: #1d4ed8; color: #fff; cursor: pointer; }
          @media print { .screen-actions { display: none; } .report-page { padding: 0; } }
        </style>
      </head>
      <body>
        ${showPrintAction ? `<div class="screen-actions"><button onclick="window.print()">Print / Save as PDF</button></div>` : ""}
        <div class="report-page">
          <div class="firm">${escapeHtml(firmName)}</div>
          <h1>${escapeHtml(title)}</h1>
          ${subtitle ? `<div class="subtitle">${escapeHtml(subtitle)}</div>` : ""}
          ${sections.map((section) => structuredReportSection(section)).join("")}
        </div>
      </body>
    </html>
  `;
  return openHtmlReportTab(html, title);
}

function structuredReportSection(section) {
  const rows = section.rows || [];
  const headers = Object.keys(rows[0] || {});
  return `
    <section>
      <h2>${escapeHtml(section.title || "")}</h2>
      ${rows.length ? `
        <table>
          <thead><tr>${headers.map((header) => `<th>${escapeHtml(header)}</th>`).join("")}</tr></thead>
          <tbody>${rows.map((row) => `<tr>${headers.map((header) => `<td>${escapeHtml(row[header] ?? "")}</td>`).join("")}</tr>`).join("")}</tbody>
        </table>
      ` : `<div class="empty">${escapeHtml(section.empty || "No records found.")}</div>`}
      ${section.total ? `<p class="total">${escapeHtml(section.total)}</p>` : ""}
    </section>
  `;
}

function renderReportsPage() {
  const fromDate = state.filters.reportFrom || "";
  const toDate = state.filters.reportTo || "";
  const all = filterFilesByReportDate(visibleFiles(), fromDate, toDate);
  const bulkReport = state.bulkBillingReports || null;
  const bulkReports = bulkReport ? [
    ["bulk-non-billed", "Files Marked Non-Billed", bulkReport.nonBilled || []],
    ["bulk-billed", "Files Marked Billed", bulkReport.billed || []],
    ["bulk-unmatched-ambiguous", "Unmatched / Ambiguous Records", bulkReport.unmatchedOrAmbiguous || []],
  ] : [];
  const feeReport = state.bulkFeeReceivedReports || null;
  const feeReports = feeReport ? [
    ["fee-received-marked", "Files Marked Fee Received", feeReport.received || []],
    ["fee-received-unmatched", "Unmatched / Ambiguous Fee Records", feeReport.unmatchedOrAmbiguous || []],
  ] : [];
  const reports = [
    ["all-files", "All Files", all, "grad-blue"],
    ["completed", "Completed", all.filter((f) => f.filed), "grad-green"],
    ["overdue", "Overdue", all.filter(isOverdue), "grad-red"],
    ["work-in-progress", "Allotted / WIP / Work Done", all.filter((f) => ["Allotted", "WIP", "Work Done"].includes(statusOf(f).label)), "grad-purple"],
    ["pending-files", "Pending Files", all.filter((f) => !isCheckedCompleted(f)), "grad-yellow"],
    ["approval-pending", "Approval Pending", all.filter(pendingApproval), "grad-yellow"],
    ["billing-pending", "Billing Pending", all.filter(completedNotBilled), "grad-pink"],
  ];
  document.querySelector("#reports").innerHTML = `
    <div class="panel">
      <div class="report-list-hero">
        <div>
          <h3>Reports & Export Centre</h3>
          <p>Download office reports in Excel or PDF format.</p>
        </div>
        <span>${all.length} records</span>
      </div>
      <div class="report-date-filter">
        <div class="field">
          <label>From</label>
          <input type="date" id="reportFromDate" value="${fromDate}">
        </div>
        <div class="field">
          <label>To</label>
          <input type="date" id="reportToDate" value="${toDate}">
        </div>
        <div class="field">
          <label>Action</label>
          <button class="secondary-button" id="clearReportDates">Clear Dates</button>
        </div>
      </div>
      <div class="grid metrics report-card-grid">
        ${reports.map(([key, title, rows, className]) => `
          <div class="metric-card report-export-card ${className}">
            <span>${title}</span>
            <strong>${rows.length}</strong>
          <p>Record(s)</p>
            <div class="report-card-actions">
              <button data-excel="${key}" ${rolePerm().export ? "" : "disabled"}>Excel</button>
              <button data-pdf="${key}" ${rolePerm().export ? "" : "disabled"}>Pdf</button>
            </div>
          </div>
        `).join("")}
      </div>
      ${bulkReport ? `
        <div class="bulk-report-panel">
          <div>
            <h3>Latest Bulk Billing Update</h3>
            <p>Source: ${escapeHtml(bulkReport.source || "Excel upload")} | Updated ${fmt((bulkReport.generatedAt || "").slice(0, 10))}</p>
          </div>
          <div class="bulk-report-summary">
            <span>Total Excel Rows <strong>${bulkReport.summary?.totalExcelRows || 0}</strong></span>
            <span>Non-Billed <strong>${bulkReport.summary?.nonBilled || 0}</strong></span>
            <span>Billed <strong>${bulkReport.summary?.billed || 0}</strong></span>
            <span>Unmatched <strong>${bulkReport.summary?.unmatched || 0}</strong></span>
            <span>Ambiguous <strong>${bulkReport.summary?.ambiguous || 0}</strong></span>
            <span>Skipped <strong>${bulkReport.summary?.skipped || 0}</strong></span>
          </div>
          <div class="report-list compact-report-list">
            ${bulkReports.map(([key, title, rows]) => `
              <div class="report-row">
                <strong>${title} <span class="small-muted">(${rows.length})</span></strong>
                <button data-bulk-excel="${key}" ${rolePerm().export ? "" : "disabled"}>Excel</button>
                <button data-bulk-pdf="${key}" ${rolePerm().export ? "" : "disabled"}>Pdf</button>
              </div>
            `).join("")}
          </div>
        </div>
      ` : ""}
      ${feeReport ? `
        <div class="bulk-report-panel">
          <div>
            <h3>Latest Fee Received Update</h3>
            <p>Source: ${escapeHtml(feeReport.source || "Excel upload")} | Updated ${fmt((feeReport.generatedAt || "").slice(0, 10))}</p>
          </div>
          <div class="bulk-report-summary">
            <span>Total Excel Rows <strong>${feeReport.summary?.totalExcelRows || 0}</strong></span>
            <span>Marked Received <strong>${feeReport.summary?.received || 0}</strong></span>
            <span>Unmatched <strong>${feeReport.summary?.unmatched || 0}</strong></span>
            <span>Ambiguous <strong>${feeReport.summary?.ambiguous || 0}</strong></span>
          </div>
          <div class="report-list compact-report-list">
            ${feeReports.map(([key, title, rows]) => `
              <div class="report-row">
                <strong>${title} <span class="small-muted">(${rows.length})</span></strong>
                <button data-fee-excel="${key}" ${rolePerm().export ? "" : "disabled"}>Excel</button>
                <button data-fee-pdf="${key}" ${rolePerm().export ? "" : "disabled"}>Pdf</button>
              </div>
            `).join("")}
          </div>
        </div>
      ` : ""}
      <div class="report-list compact-report-list">
        ${reports.map(([key, title, rows]) => `
          <div class="report-row">
            <strong>${title} <span class="small-muted">(${rows.length})</span></strong>
            <button data-excel="${key}" ${rolePerm().export ? "" : "disabled"}>Excel</button>
            <button data-pdf="${key}" ${rolePerm().export ? "" : "disabled"}>Pdf</button>
          </div>
        `).join("")}
      </div>
    </div>
  `;
  document.querySelectorAll("[data-excel]").forEach((btn) => {
    btn.onclick = () => exportExcel(btn.dataset.excel, reports.find((r) => r[0] === btn.dataset.excel)[2]);
  });
  document.querySelectorAll("[data-pdf]").forEach((btn) => {
    btn.onclick = () => exportPdf(btn.dataset.pdf, reports.find((r) => r[0] === btn.dataset.pdf)[2]);
  });
  document.querySelectorAll("[data-bulk-excel]").forEach((btn) => {
    btn.onclick = () => exportExcel(btn.dataset.bulkExcel, bulkReports.find((r) => r[0] === btn.dataset.bulkExcel)[2]);
  });
  document.querySelectorAll("[data-bulk-pdf]").forEach((btn) => {
    btn.onclick = () => exportPdf(btn.dataset.bulkPdf, bulkReports.find((r) => r[0] === btn.dataset.bulkPdf)[2]);
  });
  document.querySelectorAll("[data-fee-excel]").forEach((btn) => {
    btn.onclick = () => exportExcel(btn.dataset.feeExcel, feeReports.find((r) => r[0] === btn.dataset.feeExcel)[2]);
  });
  document.querySelectorAll("[data-fee-pdf]").forEach((btn) => {
    btn.onclick = () => exportPdf(btn.dataset.feePdf, feeReports.find((r) => r[0] === btn.dataset.feePdf)[2]);
  });
  document.querySelector("#reportFromDate").onchange = (event) => {
    state.filters.reportFrom = event.target.value;
    saveState();
    renderReportsPage();
  };
  document.querySelector("#reportToDate").onchange = (event) => {
    state.filters.reportTo = event.target.value;
    saveState();
    renderReportsPage();
  };
  document.querySelector("#clearReportDates").onclick = () => {
    state.filters.reportFrom = "";
    state.filters.reportTo = "";
    saveState();
    renderReportsPage();
  };
}

function filterFilesByReportDate(files, fromDate = "", toDate = "") {
  return (files || []).filter((file) => {
    const reportDate = file.workAllotmentDate || file.fileReceivedDate || file.lastUpdatedDate || file.dueDate;
    if (fromDate && reportDate < fromDate) return false;
    if (toDate && reportDate > toDate) return false;
    return true;
  });
}

function staffReportRows() {
  return state.users.map((user) => ({ name: user.name, role: user.role, ...staffStats(user.name) }));
}

function cleanReportRows(rows) {
  const fileReport = rows.some(isFileRecord);
  const normalized = rows.map((row) => isFileRecord(row) ? flattenFile(row) : row);
  const allowedHeaders = [
    "Client Name",
    "PAN/Reg No",
    "Service Type",
    "FY",
    "C/o",
    "Contact No",
    "Mode",
    "File Received Date",
    "Assigned Staff",
    "Work Allotment Date",
    "Re Assigned",
    "Re Assigned Date",
    "Due Date",
    "Priority",
    "Status",
    "Completed Date",
    "Checked By",
    "Checking Remarks",
    "Checked Date",
    "Billed",
    "Bill Amount",
    "Fee Received",
    "Received Amount",
    "Remarks",
  ];
  const blockedHeaders = new Set([
    "id",
    "name",
    "pan",
    "serviceType",
    "careOf",
    "contactNo",
    "contact_no",
    "mode",
    "fileReceivedDate",
    "workDone",
    "shared",
    "reportPrepared",
    "approved",
    "filed",
    "billed",
    "stages",
    "assignedStaff",
    "workAllotmentDate",
    "workStartedDate",
    "dueDate",
    "billedDate",
    "feeReceivedDate",
    "feeReceivedAmount",
    "priority",
    "lastUpdatedDate",
    "updatedAt",
    "assignedStaffId",
    "assignedStaffEmail",
    "reAssignedStaff",
    "reAssignedStaffId",
    "reAssignedStaffEmail",
  ]);
  const rawHeaders = [...new Set(normalized.flatMap((row) => Object.keys(row)))].filter((header) => !blockedHeaders.has(String(header).trim()));
  const headers = fileReport ? allowedHeaders.filter((header) => rawHeaders.includes(header)) : rawHeaders;
  const visibleHeaders = headers.filter((header) => normalized.some((row) => {
    const value = row[header];
    return value !== undefined && value !== null && String(value).trim() !== "";
  }));
  return normalized.map((row) => Object.fromEntries(visibleHeaders.map((header) => [header, row[header] ?? ""])));
}

function isFileRecord(row) {
  return row && typeof row === "object" && ("name" in row || "serviceType" in row || "fileReceivedDate" in row || "assignedStaff" in row);
}

function fileListSectionTitle() {
  const listViewTitles = {
    active: "Active Files",
    completed: "Completed Files",
    notChecked: "Not Checked Files",
    correctionRequired: "Correction Required Files",
    billed: "Billed Files",
    nonBilled: "Non-Billed Files",
    feePending: "Fee Pending Files",
    feeReceived: "Fee Received Files",
    removed: "Removed Files",
  };
  const dashboardTitles = {
    pending: "Pending Files",
    shared: "Reports Shared",
    reportsPrepared: "Reports Prepared",
    completed: "Completed Files",
    correctionRequired: "Correction Required Files",
    reAllotted: "Re-Allotted Files",
  };
  if (state.filters.listView && listViewTitles[state.filters.listView]) return listViewTitles[state.filters.listView];
  if (state.filters.dashboardKind && dashboardTitles[state.filters.dashboardKind]) return dashboardTitles[state.filters.dashboardKind];
  return "File List";
}

function fileListPdfFileName(sectionTitle) {
  const range = [state.filters.fileFrom, state.filters.fileTo].filter(Boolean).map((date) => displayDate(date)).join("-to-");
  const reportDate = displayDate(todayDate());
  const name = [sectionTitle || "File List", range || reportDate].filter(Boolean).join("-");
  return name.replace(/[^a-zA-Z0-9-]+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");
}

function fileExportDateTime() {
  return new Intl.DateTimeFormat("en-IN", {
    timeZone: "Asia/Kolkata",
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  }).format(new Date()).replace(",", "");
}

function fileExportFilterSummary() {
  const labels = {
    search: "Search",
    client: "Client",
    careOfFilter: "C/o",
    staff: "Staff",
    service: "Service",
    workflow: "Workflow",
    status: "Status",
    billing: "Billing",
    checkingStatus: "Checking",
    pan: "PAN / Regn",
    due: "Due Date",
    priority: "Priority",
    overdue: "Overdue",
    pendingApproval: "Approval Pending",
    fileFrom: "From",
    fileTo: "To",
    receivedSort: "Received Sort",
  };
  const parts = Object.entries(labels)
    .map(([key, label]) => {
      const value = String(state.filters[key] || "").trim();
      if (!value) return "";
      const displayValue = key.toLowerCase().includes("date") || ["due", "fileFrom", "fileTo"].includes(key) ? displayDate(value) : value;
      return `${label}: ${displayValue}`;
    })
    .filter(Boolean);
  return parts.length ? parts.join(" | ") : "No filters applied";
}

function filePdfText(value, fallback = "") {
  const text = String(value ?? fallback ?? "").trim();
  return text || fallback;
}

function filePdfDate(value) {
  return displayDate(normalizeImportDate(value) || value);
}

function filePdfCompletionDate(file) {
  return filePdfDate(fileActualCompletionDate(file));
}

function filePdfAmount(value) {
  return money(Number(value || 0));
}

function filePendingAmount(file) {
  return feeReceiptSummaryForFile(file).outstandingAmount;
}

function fileCrNumber(file = {}) {
  return filePdfText(file.crNo || file.crNumber || file.clientCode || file.pan);
}

function fileDpName(file = {}) {
  return filePdfText(file.dp || file.dealingPerson || file.dealtBy || file.createdBy || file.receivedBy);
}

function fileSpName(file = {}) {
  return filePdfText(file.sp || file.supervisor || file.salesPerson || file.allottedBy);
}

function fileListReportRows(files, options = {}) {
  const { format = "display" } = options;
  const section = state.filters.listView || state.filters.dashboardKind || "files";
  const sourceFiles = section === "feeReceived"
    ? sortFilesByFeeReceivedNewestFirst(files || [])
    : (section === "notChecked" ? sortFilesByCompletionNewestFirst(files || []) : (files || []));
  const rows = sourceFiles.map((file, index) => {
    const base = {
      SN: index + 1,
      "Client Name": section === "notChecked" ? clientDetailsReportText(file) : filePdfText(file.name),
      "CR No.": fileCrNumber(file),
      "Service Type": filePdfText(file.serviceType),
      "C/o": filePdfText(file.careOf, "Direct"),
      FY: filePdfText(fileFy(file), "NA"),
      "Received Date": filePdfDate(file.fileReceivedDate),
      "Work Allotted": filePdfDate(file.workAllotmentDate || file.fileReceivedDate),
      "Assigned Staff": filePdfText(file.assignedStaff, "Not Assigned"),
      DP: fileDpName(file),
      SP: fileSpName(file),
      Status: statusOf(file).label,
      Priority: filePdfText(file.priority),
      "Due Date": filePdfDate(file.dueDate),
      Remarks: filePdfText(file.remarks),
    };
    if (section === "completed") {
      return {
        SN: base.SN,
        "Client Name": base["Client Name"],
        "PAN / Reg No.": filePdfText(fileRegistrationNumber(file), "Not Available"),
        "Service Type": base["Service Type"],
        FY: base.FY,
        "C/o": base["C/o"],
        "Completion Date": filePdfCompletionDate(file),
        "Done By": filePdfText(file.completedBy || file.workDoneBy || file.assignedStaff, "Not Assigned"),
      "Checking Status": filePdfText(checkingStatusOf(file).label, "-"),
      "Checked By": filePdfText(file.checkedBy, "-"),
      "Checked Date": filePdfDate(file.checkedDate),
      "Billing Status": completedFileBillingCategory(file),
        Remarks: base.Remarks,
      };
    }
    if (section === "notChecked") {
      return {
        SN: base.SN,
        "Client Name": base["Client Name"],
        "Service Type": base["Service Type"],
        "Assigned Staff": base["Assigned Staff"],
        "Completion Date": filePdfCompletionDate(file),
        "Submitted for Checking": filePdfDate(file.submittedForCheckingDate || file.submitted_at || fileActualCompletionDate(file)),
        "Checking Status": filePdfText(checkingStatusOf(file).label, "-"),
        "Correction Status": filePdfText(file.correctionStatus || checkingStatusOf(file).label, "-"),
        "Correction Reason": filePdfText(file.correctionReason || file.checkingRemarks || file.remarks),
      };
    }
    if (section === "billed") {
      return {
        SN: base.SN,
        "Client Name": base["Client Name"],
        "Service Type": base["Service Type"],
        "Completion Date": filePdfCompletionDate(file),
        ...billedFilesReportFields(file),
      };
    }
    if (section === "nonBilled") {
      return nonBilledReportRow(file, index);
    }
    if (section === "feePending") {
      return feePendingReportRow(file, index, { format });
    }
    if (section === "feeReceived") {
        return feeReceivedFilesReportRow(file, index, { format });
    }
    return {
      SN: base.SN,
      "Client Name": base["Client Name"],
      "CR No.": base["CR No."],
      "Service Type": base["Service Type"],
      "Received Date": base["Received Date"],
      "Assigned Staff": base["Assigned Staff"],
      DP: base.DP,
      SP: base.SP,
      Status: base.Status,
      Priority: base.Priority,
      "Due Date": base["Due Date"],
    };
  });
  return ["feePending", "feeReceived"].includes(section)
    ? appendFeeReceiptTotals(rows, sourceFiles, { numeric: section === "feePending" && format === "excel" })
    : rows;
}

function completedFilesReportHeading(files = []) {
  return [
    "Muhammad & Associates",
    "Chartered Accountants",
    `Generated: ${fileExportDateTime()} | Records: ${files.length} | Filters: ${completedPdfFilterSummary()}`,
    "COMPLETED FILES REPORT",
  ];
}

function completedPdfFilterSummary() {
  const config = configuredFinancialFilterConfig("completed");
  const active = config ? configuredFinancialActiveFilters(config) : [];
  return active.length
    ? active.map((field) => `${field.label}: ${configuredFinancialFilterValueLabel(field, field.value)}`).join(" | ")
    : "No filters applied";
}

function completedPdfRecords(sourceFiles = []) {
  return sourceFiles.map((file, index) => ({
    index: index + 1,
    client: `${filePdfText(file.name)}\n${filePdfText(fileRegistrationNumber(file), "Regn No. Not Available")} · FY ${filePdfText(fileFy(file), "NA")}`,
    service: `${filePdfText(file.serviceType)}\nC/o: ${filePdfText(file.careOf, "Direct")}`,
    completion: `${filePdfCompletionDate(file)}\nDone by: ${filePdfText(file.completedBy || file.workDoneBy || file.assignedStaff, "Not Assigned")}`,
    checking: `${filePdfText(checkingStatusOf(file).label, "-")}\n${filePdfText(file.checkedBy, "Not checked")}${file.checkedDate ? ` · ${filePdfDate(file.checkedDate)}` : ""}`,
    billing: completedFileBillingCategory(file),
    priority: filePdfText(file.priority, "Medium"),
    remarks: filePdfText(file.remarks, "-"),
  }));
}

function completedPdfSummary(sourceFiles = []) {
  return sourceFiles.reduce((summary, file) => {
    summary.total += 1;
    const checking = checkingStatusOf(file).label;
    if (checking === "Checked") summary.checked += 1;
    else if (checking === "Returned for Correction") summary.correction += 1;
    else summary.notChecked += 1;
    const billing = completedFileBillingCategory(file);
    if (billing === "Billed") summary.billed += 1;
    else if (billing === "Non Billable") summary.nonBillable += 1;
    else summary.unbilled += 1;
    return summary;
  }, { total: 0, checked: 0, notChecked: 0, correction: 0, billed: 0, unbilled: 0, nonBillable: 0 });
}

function drawCompletedPdfFirstHeader(doc, context) {
  const { pageWidth, assets, generatedAt, generatedBy, filterSummary, summary } = context;
  const margin = 30;
  try { doc.addImage(assets.logo, "PNG", margin, 20, 35, 35); } catch { /* Branded text remains available. */ }
  doc.setTextColor(...BILLED_PDF_COLORS.navy);
  doc.setFont("DejaVuSans", "bold"); doc.setFontSize(14); doc.text("Muhammad & Associates", 73, 31);
  doc.setFont("DejaVuSans", "normal"); doc.setFontSize(8.2); doc.text("Chartered Accountants", 73, 46);
  doc.setFont("DejaVuSans", "bold"); doc.setFontSize(15); doc.text("COMPLETED FILES REPORT", pageWidth / 2, 62, { align: "center" });
  doc.setDrawColor(...BILLED_PDF_COLORS.blue); doc.setLineWidth(1.5); doc.line(pageWidth / 2 - 88, 69, pageWidth / 2 + 88, 69);
  doc.setFillColor(...BILLED_PDF_COLORS.lightBlue); doc.setDrawColor(...BILLED_PDF_COLORS.border); doc.roundedRect(margin, 78, pageWidth - margin * 2, 34, 3, 3, "FD");
  doc.setTextColor(...BILLED_PDF_COLORS.text); doc.setFont("DejaVuSans", "normal"); doc.setFontSize(6.7);
  doc.text(`Generated: ${generatedAt}  |  Records: ${summary.total}  |  Generated by: ${generatedBy}`, margin + 8, 91);
  doc.text(`Filters: ${billedPdfShortText(filterSummary, 145)}  |  Sort: ${state.filters.completedSort || "Completion Date - Newest First"}`, margin + 8, 103);
  drawBilledPdfCards(doc, [
    ["Completed Files", String(summary.total), BILLED_PDF_COLORS.navy, BILLED_PDF_COLORS.lightBlue],
    ["Checked", String(summary.checked), BILLED_PDF_COLORS.green, BILLED_PDF_COLORS.lightGreen],
    ["Not Checked", String(summary.notChecked), BILLED_PDF_COLORS.amber, BILLED_PDF_COLORS.lightAmber],
    ["Correction", String(summary.correction), BILLED_PDF_COLORS.red, BILLED_PDF_COLORS.lightRed],
    ["Billed", String(summary.billed), BILLED_PDF_COLORS.blue, BILLED_PDF_COLORS.lightBlue],
    ["Unbilled", String(summary.unbilled), BILLED_PDF_COLORS.amber, BILLED_PDF_COLORS.lightAmber],
    ["Non-Billable", String(summary.nonBillable), BILLED_PDF_COLORS.muted, BILLED_PDF_COLORS.alternate],
  ], margin, 121, pageWidth - margin * 2, 7);
}

function drawCompletedPdfCompactHeader(doc, context) {
  const { pageWidth, generatedAt, filterSummary } = context;
  doc.setTextColor(...BILLED_PDF_COLORS.navy); doc.setFont("DejaVuSans", "bold"); doc.setFontSize(8.2);
  doc.text("Muhammad & Associates", 30, 24); doc.text("Completed Files Report", pageWidth / 2, 24, { align: "center" });
  doc.setFont("DejaVuSans", "normal"); doc.setFontSize(6.5); doc.setTextColor(...BILLED_PDF_COLORS.muted);
  doc.text(generatedAt, pageWidth - 30, 24, { align: "right" }); doc.text(`Filters: ${billedPdfShortText(filterSummary, 120)}`, 30, 38, { maxWidth: pageWidth - 60 });
  doc.setDrawColor(...BILLED_PDF_COLORS.border); doc.line(30, 46, pageWidth - 30, 46);
}

async function createCompletedFilesPdfDocument(sourceFiles = []) {
  await loadPdfTools();
  const assets = await loadBilledPdfAssets();
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "a4", compress: true, putOnlyUsedFonts: true });
  registerBilledPdfFonts(doc, assets);
  const records = completedPdfRecords(sourceFiles);
  const summary = completedPdfSummary(sourceFiles);
  const context = { doc, assets, records, summary, generatedAt: fileExportDateTime(), generatedBy: state.currentUser || loggedInUser()?.name || "Not Recorded", filterSummary: completedPdfFilterSummary(), pageWidth: doc.internal.pageSize.getWidth(), pageHeight: doc.internal.pageSize.getHeight() };
  doc.autoTable({
    startY: 173,
    columns: [
      { header: "SN", dataKey: "index" }, { header: "Client Details", dataKey: "client" }, { header: "Service / C/o", dataKey: "service" },
      { header: "Completion", dataKey: "completion" }, { header: "Checking", dataKey: "checking" }, { header: "Billing Status", dataKey: "billing" },
      { header: "Priority", dataKey: "priority" }, { header: "Remarks", dataKey: "remarks" },
    ],
    body: records, theme: "grid", showHead: "everyPage", rowPageBreak: "avoid", margin: { left: 30, right: 30, top: 58, bottom: 32 },
    styles: { font: "DejaVuSans", fontSize: 7, cellPadding: { top: 4, right: 3, bottom: 4, left: 3 }, overflow: "linebreak", valign: "middle", textColor: BILLED_PDF_COLORS.text, lineColor: BILLED_PDF_COLORS.border, lineWidth: .3, minCellHeight: 28 },
    headStyles: { font: "DejaVuSans", fontStyle: "bold", fontSize: 7.2, fillColor: BILLED_PDF_COLORS.navy, textColor: [255,255,255], halign: "center", minCellHeight: 27 },
    alternateRowStyles: { fillColor: BILLED_PDF_COLORS.alternate },
    columnStyles: { index: { halign: "center", cellWidth: 24 }, client: { cellWidth: 145, fontStyle: "bold" }, service: { cellWidth: 115 }, completion: { cellWidth: 112 }, checking: { cellWidth: 120 }, billing: { halign: "center", cellWidth: 76 }, priority: { halign: "center", cellWidth: 55 }, remarks: { cellWidth: 133 } },
    willDrawPage: (data) => { if (data.pageNumber === 1) drawCompletedPdfFirstHeader(doc, context); else drawCompletedPdfCompactHeader(doc, context); },
    didParseCell: (data) => {
      if (data.section !== "body") return;
      const record = records[data.row.index];
      if (data.column.dataKey === "billing") {
        data.cell.styles.fontStyle = "bold";
        if (record.billing === "Billed") { data.cell.styles.textColor = BILLED_PDF_COLORS.green; data.cell.styles.fillColor = BILLED_PDF_COLORS.lightGreen; }
        else if (record.billing === "Non Billable") { data.cell.styles.textColor = BILLED_PDF_COLORS.muted; data.cell.styles.fillColor = BILLED_PDF_COLORS.alternate; }
        else { data.cell.styles.textColor = BILLED_PDF_COLORS.amber; data.cell.styles.fillColor = BILLED_PDF_COLORS.lightAmber; }
      }
    },
  });
  drawBilledPdfFooters(doc);
  return { doc, records, summary };
}

const BILLED_PDF_DISCOUNT_KEYS = ["discountAmount", "discount_amount", "discount"];
const BILLED_PDF_PAYABLE_KEYS = ["netBillAmount", "net_bill_amount", "payableAmount", "payable_amount", "approvedPayableAmount", "approved_payable_amount"];

function billedPdfOwnNumber(record = {}, keys = []) {
  for (const key of keys) {
    if (!Object.hasOwn(record || {}, key)) continue;
    const rawValue = record[key];
    if (rawValue === null || rawValue === undefined || String(rawValue).trim() === "") continue;
    const value = Number(rawValue);
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function billedPdfPaymentStatus(values = {}) {
  const gross = Math.max(Number(values.grossBilledAmount || 0), 0);
  const discount = Math.max(Number(values.discountAmount || 0), 0);
  const net = Math.max(Number(values.netBillAmount || 0), 0);
  const received = Math.max(Number(values.receivedAmount || 0), 0);
  const balance = Math.max(Number(values.balanceAmount || 0), 0);
  const epsilon = 0.005;
  if (gross > epsilon && net <= epsilon && discount + epsilon >= gross) return "Fully Discounted";
  if (balance <= epsilon && received + epsilon >= net) return "Received";
  if (received > epsilon && received + epsilon < net) return "Partially Received";
  if (received <= epsilon && net > epsilon) return "Not Received";
  return balance <= epsilon ? "Received" : "Not Received";
}

function billedPdfFinancialValues(input = {}) {
  const grossBilledAmount = Math.max(Number(input.grossBilledAmount || 0), 0);
  const approvedDiscountAmount = Math.min(Math.max(Number(input.approvedDiscountAmount || 0), 0), grossBilledAmount);
  const totalReceivedAmount = Math.max(Number(input.totalReceivedAmount || 0), 0);
  const approvedPayableRaw = input.approvedPayableAmount;
  const approvedPayable = approvedPayableRaw === null
    || approvedPayableRaw === undefined
    || String(approvedPayableRaw).trim() === ""
    ? Number.NaN
    : Number(approvedPayableRaw);
  let netBillAmount = Number.isFinite(approvedPayable)
    ? Math.max(approvedPayable, 0)
    : Math.max(grossBilledAmount - approvedDiscountAmount, 0);
  let balanceAmount = Math.max(netBillAmount - totalReceivedAmount, 0);
  const savedBalance = Number(input.savedBalanceAmount);
  if (input.preserveLegacyBalance && Number.isFinite(savedBalance)) {
    balanceAmount = Math.max(savedBalance, 0);
    netBillAmount = Math.max(totalReceivedAmount + balanceAmount, 0);
  }
  const values = {
    grossBilledAmount,
    discountAmount: approvedDiscountAmount,
    netBillAmount,
    receivedAmount: totalReceivedAmount,
    balanceAmount,
  };
  return { ...values, paymentStatus: billedPdfPaymentStatus(values) };
}

function billedPdfReceiptMode(receipt = {}, file = {}) {
  const linked = receipt?.id ? linkedCollectionForFeeReceipt(receipt) : linkedFeeReceiptCollection(file);
  const source = linked || receipt || file;
  const accountKey = transactionAccountKey(source, "") || transactionAccountKey(receipt, "") || transactionAccountKey(file, "");
  if (accountKey === "cash") return "Cash";
  if (accountKey === "federal_bank") return "Federal Bank";
  if (accountKey === "tmb") return "TMB";
  const rawMode = String(
    source.paymentMethod || source.payment_method || source.paymentMode || source.payment_mode || source.mode
    || receipt.paymentMode || receipt.payment_mode || file.paymentMode || file.receiptMode || "",
  ).trim();
  if (!rawMode) return "Not Recorded";
  const normalized = normalizeTransactionPaymentMethod(rawMode);
  if (normalized === "Cash") return "Cash";
  if (normalized === "Other" && !/^other$/i.test(rawMode)) return rawMode;
  return normalized;
}

function billedPdfReceiptEntries(file = {}, summary = feeReceiptSummaryForFile(file)) {
  if (summary.receipts.length) {
    return summary.receipts.map((receipt) => ({
      amount: Math.max(Number(receipt.amount || receipt.receivedAmount || receipt.received_amount || 0), 0),
      date: feeReceiptRecordDate(receipt),
      mode: billedPdfReceiptMode(receipt, file),
    })).filter((entry) => entry.amount > 0);
  }
  const hasReceiptHistory = allFeeReceiptRecordsForFile(file).length > 0;
  if (hasReceiptHistory || summary.totalReceived <= 0) return [];
  return [{
    amount: summary.totalReceived,
    date: normalizeImportDate(file.feeReceivedDate || file.receivedDate || file.received_date || file.receivedOn || file.received_on || ""),
    mode: billedPdfReceiptMode({}, file),
  }];
}

function billedPdfRecord(file = {}, index = 0) {
  const summary = feeReceiptSummaryForFile(file);
  const fileDiscount = billedPdfOwnNumber(file, BILLED_PDF_DISCOUNT_KEYS);
  const receiptDiscount = summary.receipts.reduce((total, receipt) => (
    total + Math.max(billedPdfOwnNumber(receipt, BILLED_PDF_DISCOUNT_KEYS) || 0, 0)
  ), 0);
  const hasExplicitDiscount = fileDiscount !== null
    || summary.receipts.some((receipt) => billedPdfOwnNumber(receipt, BILLED_PDF_DISCOUNT_KEYS) !== null);
  const approvedDiscountAmount = fileDiscount !== null ? fileDiscount : receiptDiscount;
  const savedApprovedPayableAmount = billedPdfOwnNumber(file, BILLED_PDF_PAYABLE_KEYS);
  const approvedPayableAmount = savedApprovedPayableAmount !== null
    && (savedApprovedPayableAmount > 0 || approvedDiscountAmount >= summary.billedAmount)
    ? savedApprovedPayableAmount
    : null;
  const savedBalanceAmount = billedPdfOwnNumber(file, ["balanceAmount", "balance_amount"]);
  const financial = billedPdfFinancialValues({
    grossBilledAmount: summary.billedAmount,
    approvedDiscountAmount,
    totalReceivedAmount: summary.totalReceived,
    approvedPayableAmount,
    savedBalanceAmount,
    preserveLegacyBalance: !hasExplicitDiscount
      && approvedPayableAmount === null
      && savedBalanceAmount !== null
      && (summary.totalReceived > 0 || savedBalanceAmount > 0),
  });
  const legacyBalancePreserved = !hasExplicitDiscount
    && approvedPayableAmount === null
    && savedBalanceAmount !== null
    && (summary.totalReceived > 0 || savedBalanceAmount > 0)
    && Math.abs(financial.netBillAmount - Math.max(summary.billedAmount - approvedDiscountAmount, 0)) > 0.005;
  const receiptEntries = billedPdfReceiptEntries(file, summary);
  const latestReceipt = receiptEntries[0] || null;
  return {
    index: index + 1,
    file,
    ...financial,
    receiptEntries,
    clientName: filePdfText(file.name, "-"),
    serviceType: filePdfText(file.serviceType, "-"),
    completedDate: filePdfCompletionDate(file) || "-",
    billedDate: filePdfDate(file.billDate || file.bill_date || file.billedDate) || "-",
    receiptDate: latestReceipt?.date ? displayDate(latestReceipt.date) : "-",
    receiptMode: latestReceipt?.mode || (financial.receivedAmount > 0 ? "Not Recorded" : "-"),
    legacyBalancePreserved,
  };
}

function billedPdfSummary(records = []) {
  return records.reduce((totals, record) => {
    totals.totalRecords += 1;
    totals.grossBilledAmount += record.grossBilledAmount;
    totals.discountAmount += record.discountAmount;
    totals.netBillAmount += record.netBillAmount;
    totals.receivedAmount += record.receivedAmount;
    totals.balanceAmount += record.balanceAmount;
    if (record.paymentStatus === "Received") totals.receivedFiles += 1;
    if (record.paymentStatus === "Partially Received") totals.partiallyReceivedFiles += 1;
    if (record.paymentStatus === "Not Received") totals.notReceivedFiles += 1;
    if (record.paymentStatus === "Fully Discounted") totals.fullyDiscountedFiles += 1;
    if (record.legacyBalancePreserved) totals.legacyBalanceFiles += 1;
    record.receiptEntries.forEach((receipt) => {
      const mode = receipt.mode || "Not Recorded";
      totals.paymentModes[mode] = (totals.paymentModes[mode] || 0) + Number(receipt.amount || 0);
    });
    return totals;
  }, {
    totalRecords: 0,
    grossBilledAmount: 0,
    discountAmount: 0,
    netBillAmount: 0,
    receivedAmount: 0,
    balanceAmount: 0,
    receivedFiles: 0,
    partiallyReceivedFiles: 0,
    notReceivedFiles: 0,
    fullyDiscountedFiles: 0,
    legacyBalanceFiles: 0,
    paymentModes: {},
  });
}

function billedPdfMoney(value) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(Number(value || 0));
}

function billedPdfFilterSummary() {
  const parts = BILLED_FILE_FILTERS
    .filter(({ key, defaultValue }) => key !== "receivedSort" && String(state.filters[key] || "") !== String(defaultValue || ""))
    .map(({ key, label }) => {
      const raw = String(state.filters[key] || "").trim();
      const value = ["due", "fileFrom", "fileTo"].includes(key) ? displayDate(raw) : raw;
      return `${label}: ${value}`;
    });
  return parts.length ? parts.join(" | ") : "No Filters Applied";
}

function billedPdfSortSummary() {
  return `Received Date - ${state.filters.receivedSort || "Newest First"}`;
}

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += 32768) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + 32768));
  }
  return btoa(binary);
}

function loadBilledPdfAssets() {
  if (billedPdfAssetsPromise) return billedPdfAssetsPromise;
  billedPdfAssetsPromise = Promise.all([
    fetch("/assets/DejaVuSans.ttf").then((response) => {
      if (!response.ok) throw new Error("PDF font could not be loaded.");
      return response.arrayBuffer();
    }),
    fetch("/assets/DejaVuSans-Bold.ttf").then((response) => {
      if (!response.ok) throw new Error("PDF bold font could not be loaded.");
      return response.arrayBuffer();
    }),
    fetch("/assets/ca-india-logo.png").then((response) => {
      if (!response.ok) throw new Error("Company logo could not be loaded.");
      return response.arrayBuffer();
    }),
  ]).then(([regular, semibold, logo]) => ({
    regular: arrayBufferToBase64(regular),
    semibold: arrayBufferToBase64(semibold),
    logo: `data:image/png;base64,${arrayBufferToBase64(logo)}`,
  })).catch((error) => {
    billedPdfAssetsPromise = null;
    throw error;
  });
  return billedPdfAssetsPromise;
}

function registerBilledPdfFonts(doc, assets) {
  doc.addFileToVFS("DejaVuSans.ttf", assets.regular);
  doc.addFont("DejaVuSans.ttf", "DejaVuSans", "normal");
  doc.addFileToVFS("DejaVuSans-Bold.ttf", assets.semibold);
  doc.addFont("DejaVuSans-Bold.ttf", "DejaVuSans", "bold");
  doc.setFont("DejaVuSans", "normal");
  if (typeof doc.setCharSpace === "function") doc.setCharSpace(0);
}

const BILLED_PDF_COLORS = {
  navy: [15, 42, 95],
  blue: [37, 99, 235],
  lightBlue: [239, 246, 255],
  border: [203, 213, 225],
  text: [15, 23, 42],
  muted: [100, 116, 139],
  green: [21, 128, 61],
  lightGreen: [236, 253, 245],
  amber: [180, 83, 9],
  lightAmber: [255, 251, 235],
  red: [185, 28, 28],
  lightRed: [254, 242, 242],
  violet: [124, 58, 237],
  lightViolet: [245, 243, 255],
  alternate: [248, 250, 252],
};

function billedPdfShortText(value, maxLength = 160) {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  return text.length > maxLength ? `${text.slice(0, maxLength - 3)}...` : text;
}

function billedPdfSummaryCardItems(summary, includeFullyDiscounted = false) {
  const items = [
    ["Gross Billed Amount", billedPdfMoney(summary.grossBilledAmount), BILLED_PDF_COLORS.blue, BILLED_PDF_COLORS.lightBlue],
    ["Total Discount", billedPdfMoney(summary.discountAmount), BILLED_PDF_COLORS.violet, BILLED_PDF_COLORS.lightViolet],
    ["Net Bill Amount", billedPdfMoney(summary.netBillAmount), BILLED_PDF_COLORS.navy, BILLED_PDF_COLORS.lightBlue],
    ["Total Received", billedPdfMoney(summary.receivedAmount), BILLED_PDF_COLORS.green, BILLED_PDF_COLORS.lightGreen],
    ["Outstanding Balance", billedPdfMoney(summary.balanceAmount), BILLED_PDF_COLORS.red, BILLED_PDF_COLORS.lightRed],
    ["Received Files", String(summary.receivedFiles), BILLED_PDF_COLORS.green, BILLED_PDF_COLORS.lightGreen],
    ["Partially Received", String(summary.partiallyReceivedFiles), BILLED_PDF_COLORS.amber, BILLED_PDF_COLORS.lightAmber],
    ["Not Received", String(summary.notReceivedFiles), BILLED_PDF_COLORS.red, BILLED_PDF_COLORS.lightRed],
  ];
  if (includeFullyDiscounted) {
    items.splice(5, 0, ["Total Records", String(summary.totalRecords), BILLED_PDF_COLORS.navy, BILLED_PDF_COLORS.lightBlue]);
    items.push(["Fully Discounted", String(summary.fullyDiscountedFiles), BILLED_PDF_COLORS.violet, BILLED_PDF_COLORS.lightViolet]);
  }
  return items;
}

function drawBilledPdfCards(doc, items, x, y, availableWidth, columns = items.length) {
  const gap = 5;
  const cardWidth = (availableWidth - gap * (columns - 1)) / columns;
  const cardHeight = 40;
  items.forEach(([label, value, accent, fill], index) => {
    const row = Math.floor(index / columns);
    const column = index % columns;
    const cardX = x + column * (cardWidth + gap);
    const cardY = y + row * (cardHeight + 6);
    doc.setFillColor(...fill);
    doc.setDrawColor(...BILLED_PDF_COLORS.border);
    doc.setLineWidth(0.45);
    doc.roundedRect(cardX, cardY, cardWidth, cardHeight, 3, 3, "FD");
    doc.setFillColor(...accent);
    doc.roundedRect(cardX, cardY, 3, cardHeight, 2, 2, "F");
    doc.setTextColor(...BILLED_PDF_COLORS.muted);
    doc.setFont("DejaVuSans", "normal");
    doc.setFontSize(5.8);
    doc.text(doc.splitTextToSize(label, cardWidth - 13).slice(0, 2), cardX + 8, cardY + 10);
    doc.setTextColor(...accent);
    doc.setFont("DejaVuSans", "bold");
    doc.setFontSize(value.length > 15 ? 7.1 : 8.1);
    doc.text(value, cardX + cardWidth - 7, cardY + 31, { align: "right" });
  });
  return y + Math.ceil(items.length / columns) * (cardHeight + 6) - 6;
}

function drawBilledPdfFirstHeader(doc, context) {
  const { pageWidth, assets, generatedAt, records, filterSummary, sortSummary, generatedBy, summary } = context;
  const margin = 30;
  try { doc.addImage(assets.logo, "PNG", margin, 20, 35, 35); } catch { /* The branded text remains if an older PDF engine cannot decode the logo. */ }
  doc.setTextColor(...BILLED_PDF_COLORS.navy);
  doc.setFont("DejaVuSans", "bold");
  doc.setFontSize(14);
  doc.text("Muhammad & Associates", 73, 31);
  doc.setFont("DejaVuSans", "normal");
  doc.setFontSize(8.2);
  doc.text("Chartered Accountants", 73, 46);
  doc.setFont("DejaVuSans", "bold");
  doc.setFontSize(15);
  doc.text("BILLED FILES REPORT", pageWidth / 2, 62, { align: "center" });
  doc.setDrawColor(...BILLED_PDF_COLORS.blue);
  doc.setLineWidth(1.5);
  doc.line(pageWidth / 2 - 72, 69, pageWidth / 2 + 72, 69);

  doc.setFillColor(...BILLED_PDF_COLORS.lightBlue);
  doc.setDrawColor(...BILLED_PDF_COLORS.border);
  doc.roundedRect(margin, 78, pageWidth - margin * 2, 34, 3, 3, "FD");
  doc.setTextColor(...BILLED_PDF_COLORS.text);
  doc.setFont("DejaVuSans", "normal");
  doc.setFontSize(6.7);
  doc.text(`Generated: ${generatedAt}  |  Records: ${records.length}  |  Generated by: ${generatedBy}`, margin + 8, 91);
  doc.text(`Filters: ${billedPdfShortText(filterSummary, 125)}  |  Sort: ${sortSummary}`, margin + 8, 103);
  drawBilledPdfCards(doc, billedPdfSummaryCardItems(summary), margin, 121, pageWidth - margin * 2, 8);
}

function drawBilledPdfCompactHeader(doc, context) {
  const { pageWidth, generatedAt, filterSummary } = context;
  doc.setTextColor(...BILLED_PDF_COLORS.navy);
  doc.setFont("DejaVuSans", "bold");
  doc.setFontSize(8.2);
  doc.text("Muhammad & Associates", 30, 24);
  doc.text("Billed Files Report", pageWidth / 2, 24, { align: "center" });
  doc.setFont("DejaVuSans", "normal");
  doc.setFontSize(6.5);
  doc.setTextColor(...BILLED_PDF_COLORS.muted);
  doc.text(generatedAt, pageWidth - 30, 24, { align: "right" });
  doc.text(`Filters: ${billedPdfShortText(filterSummary, 110)}`, 30, 38, { maxWidth: pageWidth - 60 });
  doc.setDrawColor(...BILLED_PDF_COLORS.border);
  doc.setLineWidth(0.5);
  doc.line(30, 46, pageWidth - 30, 46);
}

function billedPdfTableRows(records) {
  return records.map((record) => ({
    sn: record.index,
    client: record.clientName,
    service: record.serviceType,
    dates: `Completed: ${record.completedDate}\nBilled: ${record.billedDate}`,
    gross: billedPdfMoney(record.grossBilledAmount),
    discount: billedPdfMoney(record.discountAmount),
    net: billedPdfMoney(record.netBillAmount),
    received: billedPdfMoney(record.receivedAmount),
    balance: billedPdfMoney(record.balanceAmount),
    receipt: record.receiptEntries.length > 1
      ? `${record.receiptDate}\n${record.receiptMode} (+${record.receiptEntries.length - 1})`
      : `${record.receiptDate}\n${record.receiptMode}`,
    status: record.paymentStatus,
  }));
}

function billedPdfPaymentModeRows(summary) {
  const modes = summary.paymentModes || {};
  const preferred = ["Cash", "Federal Bank", "TMB"];
  const other = Object.keys(modes).filter((mode) => !preferred.includes(mode) && mode !== "Not Recorded").sort();
  const ordered = [...preferred, ...other, "Not Recorded"];
  const rows = ordered.map((mode) => ({
    mode,
    amount: billedPdfMoney(modes[mode] || 0),
  }));
  rows.push({ mode: "Total", amount: billedPdfMoney(summary.receivedAmount) });
  return rows;
}

function drawBilledPdfGrandTotals(doc, context) {
  const { pageWidth, pageHeight, summary } = context;
  let y = (doc.lastAutoTable?.finalY || 60) + 15;
  const requiredHeight = 235;
  if (y + requiredHeight > pageHeight - 35) {
    doc.addPage();
    drawBilledPdfCompactHeader(doc, context);
    y = 62;
  }
  doc.setFillColor(...BILLED_PDF_COLORS.lightBlue);
  doc.setDrawColor(...BILLED_PDF_COLORS.border);
  doc.roundedRect(30, y, pageWidth - 60, 112, 4, 4, "FD");
  doc.setTextColor(...BILLED_PDF_COLORS.navy);
  doc.setFont("DejaVuSans", "bold");
  doc.setFontSize(10);
  doc.text("GRAND TOTALS", 40, y + 16);
  const cardsEnd = drawBilledPdfCards(doc, billedPdfSummaryCardItems(summary, true), 40, y + 25, pageWidth - 80, 5);
  if (summary.legacyBalanceFiles > 0) {
    doc.setTextColor(...BILLED_PDF_COLORS.muted);
    doc.setFont("DejaVuSans", "normal");
    doc.setFontSize(5.8);
    doc.text(`Note: ${summary.legacyBalanceFiles} legacy record(s) preserve their saved payable and balance treatment because no separate approved discount field exists.`, 40, Math.min(cardsEnd + 9, y + 107));
  }

  let modeY = y + 127;
  const modeRows = billedPdfPaymentModeRows(summary);
  const modeTableHeight = 25 + modeRows.length * 16;
  if (modeY + modeTableHeight > pageHeight - 35) {
    doc.addPage();
    drawBilledPdfCompactHeader(doc, context);
    modeY = 66;
  }
  doc.setTextColor(...BILLED_PDF_COLORS.navy);
  doc.setFont("DejaVuSans", "bold");
  doc.setFontSize(9);
  doc.text("PAYMENT MODE SUMMARY", 30, modeY);
  doc.autoTable({
    startY: modeY + 8,
    columns: [
      { header: "Payment Mode", dataKey: "mode" },
      { header: "Received Amount", dataKey: "amount" },
    ],
    body: modeRows,
    theme: "grid",
    tableWidth: 355,
    margin: { left: 30, right: pageWidth - 385, bottom: 30 },
    styles: { font: "DejaVuSans", fontSize: 7, cellPadding: 3, textColor: BILLED_PDF_COLORS.text, lineColor: BILLED_PDF_COLORS.border, lineWidth: 0.35 },
    headStyles: { font: "DejaVuSans", fontStyle: "bold", fillColor: BILLED_PDF_COLORS.navy, textColor: [255, 255, 255] },
    alternateRowStyles: { fillColor: BILLED_PDF_COLORS.alternate },
    columnStyles: { amount: { halign: "right", cellWidth: 130 }, mode: { cellWidth: 225 } },
    didParseCell: (data) => {
      if (data.section === "body" && modeRows[data.row.index]?.mode === "Total") {
        data.cell.styles.fontStyle = "bold";
        data.cell.styles.fillColor = BILLED_PDF_COLORS.lightBlue;
      }
    },
  });
}

function drawBilledPdfFooters(doc) {
  const totalPages = doc.internal.getNumberOfPages();
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  for (let page = 1; page <= totalPages; page += 1) {
    doc.setPage(page);
    doc.setDrawColor(...BILLED_PDF_COLORS.border);
    doc.setLineWidth(0.45);
    doc.line(30, pageHeight - 25, pageWidth - 30, pageHeight - 25);
    doc.setFont("DejaVuSans", "normal");
    doc.setFontSize(6.4);
    doc.setTextColor(...BILLED_PDF_COLORS.muted);
    doc.text("CA File Tracker", 30, pageHeight - 13);
    doc.text("Confidential - For Internal Use", pageWidth / 2, pageHeight - 13, { align: "center" });
    doc.text(`Page ${page} of ${totalPages}`, pageWidth - 30, pageHeight - 13, { align: "right" });
  }
}

const FEE_PENDING_PDF_AGING_BUCKETS = [
  { label: "0–15 Days", min: 0, max: 15, text: BILLED_PDF_COLORS.green, fill: BILLED_PDF_COLORS.lightGreen },
  { label: "16–30 Days", min: 16, max: 30, text: BILLED_PDF_COLORS.blue, fill: BILLED_PDF_COLORS.lightBlue },
  { label: "31–60 Days", min: 31, max: 60, text: BILLED_PDF_COLORS.amber, fill: BILLED_PDF_COLORS.lightAmber },
  { label: "61–90 Days", min: 61, max: 90, text: [194, 65, 12], fill: [255, 247, 237] },
  { label: "Above 90 Days", min: 91, max: Number.POSITIVE_INFINITY, text: BILLED_PDF_COLORS.red, fill: BILLED_PDF_COLORS.lightRed },
];

function feePendingPdfBillingIsActive(file = {}) {
  if (!isBilledFile(file) || isRemovedFileRecord(file)) return false;
  const billingType = String(file.billingType || file.billing_type || "").trim().toLowerCase().replace(/[\s_-]+/g, " ");
  if (billingType === "non billable") return false;
  if (file.billingDeleted === true || file.billing_deleted === true
    || file.billingCancelled === true || file.billing_cancelled === true
    || file.billingReversed === true || file.billing_reversed === true) return false;
  const billingStatus = String(
    file.billingStatus || file.billing_status || file.billStatus || file.bill_status || "",
  ).trim().toLowerCase().replace(/[\s_-]+/g, " ");
  return !["deleted", "cancelled", "canceled", "reversed", "non billable"].includes(billingStatus);
}

function feePendingPdfContact(file = {}) {
  return filePdfText(
    file.contactNo || file.contact_no || file.contactNumber || file.contact_number
    || file.mobile || file.mobileNo || file.mobile_no || file.phone || file.phoneNumber || file.phone_number
    || file.clientSnapshot?.contactNo || file.clientSnapshot?.contact_no || file.clientSnapshot?.contactNumber
    || file.clientSnapshot?.mobile || file.clientSnapshot?.mobileNo || file.clientSnapshot?.phone
    || file.client_snapshot?.contactNo || file.client_snapshot?.contact_no || file.client_snapshot?.contactNumber
    || file.client_snapshot?.mobile || file.client_snapshot?.mobileNo || file.client_snapshot?.phone,
    "Not Recorded",
  );
}

function feePendingPdfAging(billDate, reportDate = indiaTodayDate()) {
  const normalizedBillDate = normalizeImportDate(billDate || "");
  const normalizedReportDate = normalizeImportDate(reportDate || "");
  if (!normalizedBillDate || !normalizedReportDate) {
    return { days: null, category: "Date Not Recorded", text: "Date Not Recorded" };
  }
  const billTime = Date.parse(`${normalizedBillDate}T00:00:00Z`);
  const reportTime = Date.parse(`${normalizedReportDate}T00:00:00Z`);
  if (!Number.isFinite(billTime) || !Number.isFinite(reportTime)) {
    return { days: null, category: "Date Not Recorded", text: "Date Not Recorded" };
  }
  const days = Math.max(Math.floor((reportTime - billTime) / MS_DAY), 0);
  const bucket = FEE_PENDING_PDF_AGING_BUCKETS.find(({ min, max }) => days >= min && days <= max)
    || FEE_PENDING_PDF_AGING_BUCKETS[0];
  return { days, category: bucket.label, text: `${days} Day${days === 1 ? "" : "s"}\n${bucket.label}` };
}

function feePendingPdfStaff(file = {}) {
  return feePendingStaffName(file);
}

function feePendingPdfRecord(file = {}, index = 0, reportDate = indiaTodayDate()) {
  const financial = billedPdfRecord(file, index);
  const billDateRaw = file.billDate || file.bill_date || file.billedDate || "";
  const completed = filePdfDate(fileActualCompletionDate(file)) || "-";
  const checkedRaw = file.checkedDate || file.checked_date || file.checkedAt || file.checked_at || "";
  const checked = filePdfDate(checkedRaw) || "-";
  const registration = filePdfText(fileRegistrationNumber(file), "Not Recorded");
  const careOf = filePdfText(
    file.careOf || file.care_of || file.c_o
    || file.clientSnapshot?.careOf || file.clientSnapshot?.care_of || file.clientSnapshot?.c_o
    || file.client_snapshot?.careOf || file.client_snapshot?.care_of || file.client_snapshot?.c_o,
    "Direct",
  );
  const staffText = feePendingPdfStaff(file);
  return {
    ...financial,
    index: index + 1,
    clientDetails: `${financial.clientName}\nPAN/Reg: ${registration}\nContact: ${feePendingPdfContact(file)}`,
    workDetails: `${financial.serviceType}\nFY: ${filePdfText(fileFy(file), "Not Recorded")}\nCompleted: ${completed}\nChecked: ${checked}`,
    careOf,
    billDetails: `Bill No: ${filePdfText(file.billNo || file.bill_number || file.invoiceNumber || file.invoiceNo, "Not Recorded")}\nBill Date: ${filePdfDate(billDateRaw) || "-"}`,
    aging: feePendingPdfAging(billDateRaw, reportDate),
    assignedStaff: feePendingStaffName(file),
    staffText,
    remarks: filePdfText(file.remarks || file.billingRemarks || file.feeRemarks, "-"),
    pendingStatus: financial.receivedAmount > 0 ? "Partially Received" : "Not Received",
  };
}

function feePendingPdfRecords(sourceFiles = [], reportDate = indiaTodayDate()) {
  return sourceFiles
    .filter(feePendingPdfBillingIsActive)
    .map((file) => feePendingPdfRecord(file, 0, reportDate))
    .filter((record) => record.balanceAmount > 0.005 && record.netBillAmount > 0.005)
    .map((record, index) => ({ ...record, index: index + 1 }));
}

function feePendingPdfSummary(records = []) {
  const aging = Object.fromEntries([
    ...FEE_PENDING_PDF_AGING_BUCKETS.map(({ label }) => label),
    "Date Not Recorded",
  ].map((label) => [label, { label, files: 0, outstandingAmount: 0 }]));
  const staff = new Map();
  const summary = records.reduce((totals, record) => {
    totals.totalRecords += 1;
    totals.grossBilledAmount += record.grossBilledAmount;
    totals.discountAmount += record.discountAmount;
    totals.netBillAmount += record.netBillAmount;
    totals.receivedAmount += record.receivedAmount;
    totals.balanceAmount += record.balanceAmount;
    if (record.pendingStatus === "Partially Received") totals.partiallyReceivedFiles += 1;
    else totals.notReceivedFiles += 1;
    if (record.aging.days !== null) totals.oldestPendingDays = Math.max(totals.oldestPendingDays, record.aging.days);
    aging[record.aging.category].files += 1;
    aging[record.aging.category].outstandingAmount += record.balanceAmount;
    const staffName = record.assignedStaff || "Not Assigned";
    const staffRow = staff.get(staffName) || { staff: staffName, files: 0, outstandingAmount: 0 };
    staffRow.files += 1;
    staffRow.outstandingAmount += record.balanceAmount;
    staff.set(staffName, staffRow);
    return totals;
  }, {
    totalRecords: 0,
    grossBilledAmount: 0,
    discountAmount: 0,
    netBillAmount: 0,
    receivedAmount: 0,
    balanceAmount: 0,
    notReceivedFiles: 0,
    partiallyReceivedFiles: 0,
    oldestPendingDays: 0,
  });
  summary.agingRows = Object.values(aging);
  summary.staffRows = [...staff.values()].sort((a, b) => b.outstandingAmount - a.outstandingAmount || a.staff.localeCompare(b.staff));
  return summary;
}

function feePendingPdfFilterSummary() {
  const config = configuredFinancialFilterConfig("feePending");
  if (!config) return "No Additional Filters Applied";
  const parts = configuredFinancialActiveFilters(config)
    .filter(({ key }) => key !== "feePendingSort")
    .map((field) => `${field.label}: ${configuredFinancialFilterValueLabel(field, field.value)}`);
  return parts.length ? parts.join(" | ") : "No Additional Filters Applied";
}

function feePendingPdfSortSummary() {
  return state.filters.feePendingSort || "Bill Date - Newest First";
}

function feePendingPdfCardItems(summary) {
  return [
    ["Gross Billed Amount", billedPdfMoney(summary.grossBilledAmount), BILLED_PDF_COLORS.blue, BILLED_PDF_COLORS.lightBlue],
    ["Approved Discounts", billedPdfMoney(summary.discountAmount), BILLED_PDF_COLORS.violet, BILLED_PDF_COLORS.lightViolet],
    ["Net Bill Amount", billedPdfMoney(summary.netBillAmount), BILLED_PDF_COLORS.navy, BILLED_PDF_COLORS.lightBlue],
    ["Amount Received", billedPdfMoney(summary.receivedAmount), BILLED_PDF_COLORS.green, BILLED_PDF_COLORS.lightGreen],
    ["Total Outstanding", billedPdfMoney(summary.balanceAmount), BILLED_PDF_COLORS.red, BILLED_PDF_COLORS.lightRed],
    ["Completely Unpaid", String(summary.notReceivedFiles), BILLED_PDF_COLORS.red, BILLED_PDF_COLORS.lightRed],
    ["Partially Received", String(summary.partiallyReceivedFiles), BILLED_PDF_COLORS.amber, BILLED_PDF_COLORS.lightAmber],
    ["Oldest Pending Days", String(summary.oldestPendingDays), BILLED_PDF_COLORS.amber, BILLED_PDF_COLORS.lightAmber],
  ];
}

